INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('common_001_ri_yue_jia_ming', '日月夹命', NULL, NULL, NULL, 'common', NULL, NULL, '日月夹命格，主大贵。太阳太阴分居命宫两侧。', NULL, 0, 0, 1771384449);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('common_002_ri_yue_tong_gong', '日月同宫', NULL, NULL, NULL, 'common', NULL, NULL, '日月同宫，阴阳交泰。', NULL, 0, 0, 1771384449);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('common_003_wu_xing_ju_quan', '五星聚全', NULL, NULL, NULL, 'common', NULL, NULL, '五星聚全于三方，主大贵。木火土金水五星皆在三方之内。', NULL, 0, 0, 1771384449);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('huo_001_huo_luo_jia_ming', '火罗夹命', NULL, NULL, NULL, 'c_706b_661f_683c_5c40', NULL, NULL, '火罗夹命，主凶。火星与罗睺分居命宫两侧。', NULL, 0, 0, 1771384449);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('jin_001_tai_bai_shou_ming', '太白守命', NULL, NULL, NULL, 'c_91d1_661f_683c_5c40', NULL, NULL, '太白金星在命宫，入庙为贵。', NULL, 0, 0, 1771384449);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('xian_001_xian_yu_ji', '限遇计都', NULL, NULL, NULL, 'c_884c_9650_683c_5c40', NULL, NULL, '行限遇计都，主有灾祸。', NULL, 0, 0, 1771384449);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('time_001_zhou_sheng_ri_li', '昼生日立命', NULL, NULL, NULL, 'c_65f6_95f4_683c_5c40', NULL, NULL, '昼生人，太阳守命为吉格。', NULL, 0, 0, 1771384449);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('huo_001_zhu_yi_chi_ri', '朱衣驰日', NULL, NULL, NULL, 'c_706b_661f_683c_5c40', NULL, NULL, '朱衣驰日，朝廷宣使奏差。火会日，与马元同行。', NULL, 0, 0, 1771384449);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('huo_002_bei_hai_tiao_deng', '北海挑灯', NULL, NULL, NULL, 'c_706b_661f_683c_5c40', NULL, NULL, '北海挑灯，位居宰辅。', NULL, 0, 0, 1771384449);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('huo_003_bei_yuan_hui_chun', '北苑回春', NULL, NULL, NULL, 'c_706b_661f_683c_5c40', NULL, NULL, '北苑回春，状元及第。北子位苑，指火也，冬火为用，星居子照，值命身与太阳。', NULL, 0, 0, 1771384449);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('huo_004_chang_hong_guan_ri', '长虹贯日', NULL, NULL, NULL, 'c_706b_661f_683c_5c40', NULL, NULL, '长虹贯日，早冠判臣。', NULL, 0, 0, 1771384449);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('huo_005_zhou_huo_ye_tu', '昼火夜土', NULL, NULL, NULL, 'c_706b_661f_683c_5c40', NULL, NULL, '火土分昼夜之忌。昼生忌火罗，夜生忌土计。', NULL, 0, 0, 1771384449);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('huo_006_huo_luo_xia_hui', '火罗夏会', NULL, NULL, NULL, 'c_706b_661f_683c_5c40', NULL, NULL, '火罗夏会，多招哭泣之灾。夏生遇火罗，有刑伤哭泣之灾。', NULL, 0, 0, 1771384449);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('huo_007_jin_huo_yi_yuan', '金火易垣', NULL, NULL, NULL, 'c_706b_661f_683c_5c40', NULL, NULL, '火金不可易垣。火不可入金垣，金不可入火垣，疑其相攻相克也。', NULL, 0, 0, 1771384449);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('huo_008_zhou_huo_fan_ri', '昼火犯日', NULL, NULL, NULL, 'c_706b_661f_683c_5c40', NULL, NULL, '火化暗，昼生忌与太阳同躔。', NULL, 0, 0, 1771384449);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('huo_009_huo_tu_ba_sha', '火土八杀', NULL, NULL, NULL, 'c_706b_661f_683c_5c40', NULL, NULL, '残疾者，火罗土杂于难宫。火罗土聚于八杀宫，必然残疾也。', NULL, 0, 0, 1771384449);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('huo_010_huo_luo_ru_ji', '火罗入疾', NULL, NULL, NULL, 'c_706b_661f_683c_5c40', NULL, NULL, '火罗不宜入疾厄，如此者，男有暴病，女多产难，若非自灾必伤骨肉。', NULL, 0, 0, 1771384449);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('huo_011_huo_ju_song_lu', '火居宋鲁', NULL, NULL, NULL, 'c_706b_661f_683c_5c40', NULL, NULL, '火居宋鲁，纵日诞而禄自盈余（火在卯戌）。', NULL, 0, 0, 1771384449);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('huo_012_huo_tu_de_niu', '火土得牛', NULL, NULL, NULL, 'c_706b_661f_683c_5c40', NULL, NULL, '火土会于牛宫，不独龟龄而已（火土会牛在丑）。', NULL, 0, 0, 1771384449);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('huo_013_zhu_que_fan_shen', '朱雀犯身', NULL, NULL, NULL, 'c_706b_661f_683c_5c40', NULL, NULL, '多招横祸，火罗犯于身命之中（火罗朱雀星也）。', NULL, 0, 0, 1771384449);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('huo_014_huo_zai_ba_gong', '火在八宫', NULL, NULL, NULL, 'c_706b_661f_683c_5c40', NULL, NULL, '求医何数？火在八宫（火主血光）。日日有灾，盖谓八宫见火（疾厄宫，怕见火罗）。疾厄遇火孛，女多产死之因。', NULL, 0, 0, 1771384449);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('huo_015_shui_huo_xiang_zhan', '水火相战', NULL, NULL, NULL, 'c_706b_661f_683c_5c40', NULL, NULL, '一身迍蹇，火星怕与水星交战。水火同临寿必损。[水火守身命]', NULL, 0, 0, 1771384449);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('huo_016_huo_lin_yan_di', '火临燕地', NULL, NULL, NULL, 'c_706b_661f_683c_5c40', NULL, NULL, '性逸素无拘，盖喜火临燕地（火星在寅宫）。', NULL, 0, 0, 1771384449);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('huo_017_huo_song_wei_rong', '火宋为荣', NULL, NULL, NULL, 'c_706b_661f_683c_5c40', NULL, NULL, '火躔宋以为荣（火居卯位）。', NULL, 0, 0, 1771384449);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('huo_018_huo_feng_tai_yi', '火逢太乙', NULL, NULL, NULL, 'c_706b_661f_683c_5c40', NULL, NULL, '火躔宋以为荣（火居卯位），见太乙则早归泉路（孛必克火）。', NULL, 0, 0, 1771384449);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('huo_019_huo_wu_feng_mu', '火五逢木', NULL, NULL, NULL, 'c_706b_661f_683c_5c40', NULL, NULL, '火临五位见木，方显儿孙（火木相生临儿）。', NULL, 0, 0, 1771384449);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('huo_020_ying_huo_zai_mao', '荧惑在卯', NULL, NULL, NULL, 'c_706b_661f_683c_5c40', NULL, NULL, '南方荧惑在卯宫，贵饶衣食（火星居卯）。', NULL, 0, 0, 1771384450);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('huo_021_huo_bei_shen_you', '火孛申酉', NULL, NULL, NULL, 'c_706b_661f_683c_5c40', NULL, NULL, '中年命蹇，火孛而守申酉（火孛同申或酉）。', NULL, 0, 0, 1771384450);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('huo_022_huo_ru_jin_xiang', '火入金乡', NULL, NULL, NULL, 'c_706b_661f_683c_5c40', NULL, NULL, '火入金乡，此命早抛兄弟（火怕辰酉位）。', NULL, 0, 0, 1771384450);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('huo_023_jin_huo_tong_cai', '金火同财', NULL, NULL, NULL, 'c_706b_661f_683c_5c40', NULL, NULL, '少失资财，金火同居财位（金火忌守财宫）。', NULL, 0, 0, 1771384450);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('huo_024_shui_huo_ju_tian', '水火居田', NULL, NULL, NULL, 'c_706b_661f_683c_5c40', NULL, NULL, '水火并居田宅，破家荡产（水火忌居田宅）。祖财困辱田宅，火被水来侵。[水火会田宅]', NULL, 0, 0, 1771384450);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('huo_025_huo_ming_chong_kui', '火明冲魁', NULL, NULL, NULL, 'c_706b_661f_683c_5c40', NULL, NULL, '卯为太冲，戌为河魁，火星临此二宫，兵将之权。', NULL, 0, 0, 1771384450);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('huo_026_huo_yao_lin_yang', '火曜临阳', NULL, NULL, NULL, 'c_706b_661f_683c_5c40', NULL, NULL, '一天黯淡，只缘火曜临阳。[火日同宫]', NULL, 0, 0, 1771384450);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('huo_027_huo_jin_zi_wei', '火金子位', NULL, NULL, NULL, 'c_706b_661f_683c_5c40', NULL, NULL, '火金子位，如此者非贫即夭。', NULL, 0, 0, 1771384450);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('huo_028_huo_luo_chan_ming', '火罗躔命', NULL, NULL, NULL, 'c_706b_661f_683c_5c40', NULL, NULL, '性躁，猖狂，火罗同躔命度。[火罗刚暴星也]', NULL, 0, 0, 1771384450);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('huo_029_huo_xing_nan_lv', '火行南律', NULL, NULL, NULL, 'c_706b_661f_683c_5c40', NULL, NULL, '性敏巧明，火行南律。[火星得局也]', NULL, 0, 0, 1771384450);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('huo_030_huo_bei_tong_ming', '火孛通明', NULL, NULL, NULL, 'c_706b_661f_683c_5c40', NULL, NULL, '火孛通明必外迁。[火孛在命]', NULL, 0, 0, 1771384450);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('huo_031_huo_yao_dang_quan', '火曜当权', NULL, NULL, NULL, 'c_706b_661f_683c_5c40', NULL, NULL, '火若当权，恣行酷毒。[火性烈燥急]', NULL, 0, 0, 1771384450);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('huo_032_huo_luo_lin_fu', '火罗临父', NULL, NULL, NULL, 'c_706b_661f_683c_5c40', NULL, NULL, '火罗若临父母，幼失慈亲。[火罗炎威酷毒]', NULL, 0, 0, 1771384450);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('huo_033_huo_bei_lin_kun', '火孛临坤', NULL, NULL, NULL, 'c_706b_661f_683c_5c40', NULL, NULL, '火孛临坤，未免腰背屈曲。[火孛临申]', NULL, 0, 0, 1771384450);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('huo_034_jin_huo_zhan_chen_you', '金火战辰酉', NULL, NULL, NULL, 'c_706b_661f_683c_5c40', NULL, NULL, '金火战于辰酉，肺心咳嗽。[火主心金主肺]', NULL, 0, 0, 1771384450);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('huo_035_huo_xing_tui_liu', '火星退留', NULL, NULL, NULL, 'c_706b_661f_683c_5c40', NULL, NULL, '火若退而迟留，难堪酒糟。[必患酒糟]', NULL, 0, 0, 1771384450);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('huo_036_huo_yue_zheng_guang', '火月争光', NULL, NULL, NULL, 'c_706b_661f_683c_5c40', NULL, NULL, '火逢月朗而无权。望夜火月争光。月圆火焰，奈争斗而无成。上弦后，下弦前，夜月忌火罗。', NULL, 0, 0, 1771384450);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('huo_037_jin_de_huo_ming', '金得火明', NULL, NULL, NULL, 'c_706b_661f_683c_5c40', NULL, NULL, '金得火明而焕发。[秋金见火为奇]', NULL, 0, 0, 1771384450);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('huo_038_xia_huo_jian_yue', '夏火见月', NULL, NULL, NULL, 'c_706b_661f_683c_5c40', NULL, NULL, '夏火不妨见月。[夏火本炎，遇太阴以解酷热，火得令能助月]', NULL, 0, 0, 1771384450);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('huo_039_xia_huo_feng_qi', '夏火逢气', NULL, NULL, NULL, 'c_706b_661f_683c_5c40', NULL, NULL, '盛夏之火何，须木气生扶。[木至六月则绝而不旺，见火反干]', NULL, 0, 0, 1771384450);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('huo_040_dong_tu_hui_huo', '冻土会火', NULL, NULL, NULL, 'c_706b_661f_683c_5c40', NULL, NULL, '冰冻之土会火，始能发用。', NULL, 0, 0, 1771384450);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('huo_041_huo_yue_tong_xiao', '火月同宵', NULL, NULL, NULL, 'c_706b_661f_683c_5c40', NULL, NULL, '残晦之月，见火增辉。[初八以前，二十以后，三方对照得火相助]', NULL, 0, 0, 1771384450);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('huo_042_ying_huo_ju_yuan', '荧惑居垣', NULL, NULL, NULL, 'c_706b_661f_683c_5c40', NULL, NULL, '荧惑居垣。', NULL, 0, 0, 1771384450);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('huo_043_huo_xing_sheng_dian', '火星升殿', NULL, NULL, NULL, 'c_706b_661f_683c_5c40', NULL, NULL, '火星升殿：火躔尾室觜翼四宿。', NULL, 0, 0, 1771384450);
