INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('huo_046_zhu_que_yu_fu', '朱雀御符', NULL, NULL, NULL, 'c_706b_661f_683c_5c40', NULL, NULL, '朱雀御符：巳午月生，火日同宫。火为朱雀星。', NULL, 0, 0, 1771384450);
