INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('huo_051_huo_qi_zhi_quan', '火气职权', NULL, NULL, NULL, 'c_706b_661f_683c_5c40', NULL, NULL, '火气职权：火为用神，入庙旺宫合格。', NULL, 0, 0, 1771384450);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('huo_052_huo_jin_shi_yue', '火金侍月', NULL, NULL, NULL, 'c_706b_661f_683c_5c40', NULL, NULL, '火金侍月：火金为用神，临垣庙，夜生者妙。', NULL, 0, 0, 1771384450);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('huo_053_chu_gan_ru_kun', '出干入坤', NULL, NULL, NULL, 'c_706b_661f_683c_5c40', NULL, NULL, '出干入坤。', NULL, 0, 0, 1771384450);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('huo_054_shui_huo_ji_ji', '水火既济', NULL, NULL, NULL, 'c_706b_661f_683c_5c40', NULL, NULL, '水火既济：水子火午，命坐子午。', NULL, 0, 0, 1771384450);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('huo_055_feng_lei_gu_wu', '风雷鼓舞', NULL, NULL, NULL, 'c_706b_661f_683c_5c40', NULL, NULL, '风雷鼓舞：水巳火卯，命辰合格。', NULL, 0, 0, 1771384450);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('huo_056_huo_luo_fan_ri', '火罗犯日', NULL, NULL, NULL, 'c_706b_661f_683c_5c40', NULL, NULL, '火罗犯日：昼日怕火罗同宫，掌刃雄尤忌。', NULL, 0, 0, 1771384450);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('huo_057_huo_bei_gong_zhan', '火孛共战', NULL, NULL, NULL, 'c_706b_661f_683c_5c40', NULL, NULL, '火孛共战：火为用神则损矣。', NULL, 0, 0, 1771384450);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('huo_058_feng_lei_xiang_bo', '风雷相薄', NULL, NULL, NULL, 'c_706b_661f_683c_5c40', NULL, NULL, '风雷相薄。', NULL, 0, 0, 1771384451);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('huo_059_shui_huo_xiang_she', '水火相射', NULL, NULL, NULL, 'c_706b_661f_683c_5c40', NULL, NULL, '水火相射：水午火子，或木卯戌，或火巳申。', NULL, 0, 0, 1771384451);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('huo_060_yu_hou_xiao_yue', '玉猴啸月', NULL, NULL, NULL, 'c_706b_661f_683c_5c40', NULL, NULL, '玉猴啸月：火觜月毕，坐命火月度，夜生贵。', NULL, 0, 0, 1771384451);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('huo_061_hu_xiao_yuan_yin', '虎啸猿吟', NULL, NULL, NULL, 'c_706b_661f_683c_5c40', NULL, NULL, '虎啸猿吟：木尾火觜，亥命大贵，巳命大富。', NULL, 0, 0, 1771384451);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('huo_062_huo_bei_qing_tian', '火孛擎天', NULL, NULL, NULL, 'c_706b_661f_683c_5c40', NULL, NULL, '火孛擎天：火室孛壁，水轸火翼，皆主富贵。', NULL, 0, 0, 1771384451);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('huo_063_ba_sha_chao_tian', '八杀朝天', NULL, NULL, NULL, 'c_706b_661f_683c_5c40', NULL, NULL, '八千朝天：如戌命火，又未命土，或辰命金。此三星独占天门，得时为上。惟金火尤重，夜生显贵之人也。', NULL, 0, 0, 1771384451);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('huo_064_zhu_que_dang_quan', '朱雀当权', NULL, NULL, NULL, 'c_706b_661f_683c_5c40', NULL, NULL, '夏生人见火星在巳午安命，乃朱雀当权。', NULL, 0, 0, 1771384451);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('huo_065_li_kan_jiao_hui', '离坎交会', NULL, NULL, NULL, 'c_706b_661f_683c_5c40', NULL, NULL, '离坎交会：水星禀北方坎宫之气，火星禀南方离宫之气，夜生人火星在命中，水星正照，乃合此格，此格最主为人气概精神，法能剸裁繁剧，禄位优厚。若水火二星同守命宫，则是煎熬星矣，反主灾祸。', NULL, 0, 0, 1771384451);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('huo_066_zi_xing_fu_zheng', '子行父政', NULL, NULL, NULL, 'c_706b_661f_683c_5c40', NULL, NULL, '子行父政：太阳乃火之精，太阴为水之副，故日为父，火为子。且太阳之庙在午，太阳居之当然也，今则太阳却居子，火星却在午，又于午上安命，是父之政子乃行也；此格主人艰难于始，逸乐于终，以其干蛊之早也。谓且父之创制，子当继之，父之德政，予当行之。此谓人有贤子而继父志，不亦善乎！另有子承父位：午宫星度立命，火星入命，以占父位，太阳飞入卯宫房度，卯乃子位，父居之，必主父子不和，兄弟失伦，行限见木，非犯刑而死，定主恶疾而亡。', NULL, 0, 0, 1771384451);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('huo_067_huo_shui_wei_ji', '火水未济', NULL, NULL, NULL, 'c_706b_661f_683c_5c40', NULL, NULL, '火水未济：火先入宫，水后入宫，同居一宫，以照命者是也。盖火自上炎，水自下注，相违而不相向，安得能和而能济。曰：未济男之穷也。格中带此者，主贫贱。此系忌格。', NULL, 0, 0, 1771384451);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('huo_068_shui_huo_ji_ji_2', '水火既济', NULL, NULL, NULL, 'c_706b_661f_683c_5c40', NULL, NULL, '水火既济：水先入宫，火后入宫，同居一位以照命者是也。盖水性润下，火性炎上，上下相得，而不相违，切嫌一二凶星入侵，则反生祸。更若水星为宫主，为命主，为禄主，则福最厚，富贵双全之命也。', NULL, 0, 0, 1771384451);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('huo_069_shui_huo_xiang_xing', '水火相刑', NULL, NULL, NULL, 'c_706b_661f_683c_5c40', NULL, NULL, '水火相刑：歌曰：命立卯宫在房度，生于夏令主炎库。行限午宫见水星，水入午宫宜柳土。反凶为吉福无边，金玉争光敌国富。若教脱水鬼门关，五十三四归泉路。', NULL, 0, 0, 1771384451);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('huo_070_nv_huo_wei_fu', '女火为夫', NULL, NULL, NULL, 'c_706b_661f_683c_5c40', NULL, NULL, '女火为夫：妇人只要看火荧，火是夫星为正宗。', NULL, 0, 0, 1771384451);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('huo_071_huo_luo_nong_xue', '火罗脓血', NULL, NULL, NULL, 'c_706b_661f_683c_5c40', NULL, NULL, '火罗脓血：火罗为性多毒恶，脓血夭亡灾不薄。', NULL, 0, 0, 1771384451);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('huo_072_huo_ming_tian_shi', '火明天市', NULL, NULL, NULL, 'c_706b_661f_683c_5c40', NULL, NULL, '火星卯宫，贵格。', NULL, 0, 0, 1771384451);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('huo_073_huo_hao_wen_chang', '火号文昌', NULL, NULL, NULL, 'c_706b_661f_683c_5c40', NULL, NULL, '火在未宫，贵格。', NULL, 0, 0, 1771384451);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('huo_074_huo_gui_kun_di', '火归坤地', NULL, NULL, NULL, 'c_706b_661f_683c_5c40', NULL, NULL, '火申宫，贵格。', NULL, 0, 0, 1771384451);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('huo_075_huo_ju_lou_su', '火居娄宿', NULL, NULL, NULL, 'c_706b_661f_683c_5c40', NULL, NULL, '火白羊娄宿。贵格。', NULL, 0, 0, 1771384451);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('huo_076_jin_huo_tong_zhou', '金火同周', NULL, NULL, NULL, 'c_706b_661f_683c_5c40', NULL, NULL, '金火午宫，贱格。', NULL, 0, 0, 1771384451);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('huo_077_yi_yang_lai_fu', '一阳来复', NULL, NULL, NULL, 'c_706b_661f_683c_5c40', NULL, NULL, '夜生人独火居子，为一阳来复，女土安命尤奇。', NULL, 0, 0, 1771384451);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('huo_078_huo_luo_feng_sha', '火罗逢煞', NULL, NULL, NULL, 'c_706b_661f_683c_5c40', NULL, NULL, '火罗怕头，更带刃雄，廉锋，耗符等煞，金命限人愈甚。', NULL, 0, 0, 1771384451);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('huo_079_jue_huo_da_ming', '爝火大明', NULL, NULL, NULL, 'c_706b_661f_683c_5c40', NULL, NULL, '火星落空谓之爝火大明，乃是离中火虚，反主发达，夜生尤妙，盖火遇夜则明故也。', NULL, 0, 0, 1771384451);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('huo_080_huo_de_mu_ji', '火得木济', NULL, NULL, NULL, 'c_706b_661f_683c_5c40', NULL, NULL, '春令之火，正二月之时寒气未消，最喜火罗木气互度，见太阴，夜生光彩，文武富贵。火本酷烈，逢木慈仁，以善化恶，以刚制柔，刚柔相济，贵而能决，威福权衡。', NULL, 0, 0, 1771384451);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('huo_081_tao_hua_gun_lang', '桃花滚浪', NULL, NULL, NULL, 'c_706b_661f_683c_5c40', NULL, NULL, '春末夏初之际，火入水宫，水入火地，叫做桃花滚浪，水暖花红，名利双清。', NULL, 0, 0, 1771384451);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('huo_082_zi_lai_jiu_mu', '子来救母', NULL, NULL, NULL, 'c_706b_661f_683c_5c40', NULL, NULL, '春末夏初之际，火入水宫，水入火地，称为桃花滚浪，水暖花红，名利双清。但火不宜与水孛同行，谓之受克。逢土有救，能破水孛之气，名曰：子来救母，禄自丰盈。见金为党鬼，独火之气脉虚也。', NULL, 0, 0, 1771384451);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('huo_083_wan_wu_cui_ku', '万物摧枯', NULL, NULL, NULL, 'c_706b_661f_683c_5c40', NULL, NULL, '夏末秋初之火，斯时秋阳杲杲，借水以济其盛，乃刚柔变化，最不宜与木气同照，火罗朝拱，太阳无水济润，迎照度限，万物破坏。', NULL, 0, 0, 1771384451);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('huo_084_yi_bei_ji_huo', '一孛济火', NULL, NULL, NULL, 'c_706b_661f_683c_5c40', NULL, NULL, '夏末秋初之火，斯时秋阳杲杲，借水以济其盛，乃刚柔变化，最不宜与木气同照。火罗朝拱，太阳无水济润，迎照度限，万物破坏。经云：火焰而无水淘溶，纵发而早年夭折。', NULL, 0, 0, 1771384451);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('huo_085_gao_miao_de_yu', '稿苗得雨', NULL, NULL, NULL, 'c_706b_661f_683c_5c40', NULL, NULL, '夏末秋初之火，斯时秋阳杲杲，借水以济其盛，乃刚柔变化，最不宜与木气同照。火罗朝拱，太阳无水济润，迎照度限，万物破坏枯，一陷千丈，如有一水贯日，一孛济火，为之淋漓普济苍生，万物苏茂精神宛转富贵。经云：火焰而无水淘溶，纵发而早年夭折。又有先见火日，后见水孛，此谓之久旱干焦，稿苗得雨，先主艰难而后快活。', NULL, 0, 0, 1771384451);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('huo_086_jiu_yu_feng_qing', '久雨逢晴', NULL, NULL, NULL, 'c_706b_661f_683c_5c40', NULL, NULL, '夏末秋初之火，斯时秋阳杲杲，借水以济其盛，乃刚柔变化，最不宜与木气同照。火罗朝拱，太阳无水济润，迎照度限，万物破坏枯，一陷千丈，如有一水贯日，一孛济火，为之淋漓普济苍生，万物苏茂精神宛转富贵。经云：火焰而无水淘溶，纵发而早年夭折。又有先见水，后见火日，谓之久雨逢晴，先主快活而后艰辛。', NULL, 0, 0, 1771384451);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('huo_087_mu_qi_fu_huo', '木气扶火', NULL, NULL, NULL, 'c_706b_661f_683c_5c40', NULL, NULL, '冬令之火，斯时黑帝司权，水德用事而火失时，最喜木气相扶。', NULL, 0, 0, 1771384451);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('huo_088_ye_huo_guan_ri', '夜火贯日', NULL, NULL, NULL, 'c_706b_661f_683c_5c40', NULL, NULL, '冬令之火，斯时黑帝司权，水德用事而火失时，若夜火贯日，纳入禄印爵贵佐之，反能富贵名扬天下之人也。', NULL, 0, 0, 1771384451);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('huo_089_huo_qi_mai_xu', '火气脉虚', NULL, NULL, NULL, 'c_706b_661f_683c_5c40', NULL, NULL, '冬令之火，斯时黑帝司权，水德用事而火失时，其火最忌水孛土计罗喉相互作用，火之气脉虚矣。', NULL, 0, 0, 1771384451);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('huo_090_jing_shen_yun_zhuan', '精神运转', NULL, NULL, NULL, 'c_706b_661f_683c_5c40', NULL, NULL, '冬令之火，斯时黑帝司权，水德用事而火失时，其火最忌水孛土计罗喉相互作用，火之气脉虚矣。如有一木飞来泄水之气，助火出色，所谓水生木，木生火，命脉健矣。此乃精神转运，合为贵论。', NULL, 0, 0, 1771384451);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('jin_001_jun_chen_qing_hui', '君臣庆会', NULL, NULL, NULL, 'c_91d1_661f_683c_5c40', NULL, NULL, '君臣庆会，钟鸣鼎食之家。金水为官福恩令命元，朝辅太阳者是。', NULL, 0, 0, 1771384451);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('jin_002_shan_xiao_cheng_bao', '山啸呈宝', NULL, NULL, NULL, 'c_91d1_661f_683c_5c40', NULL, NULL, '土金同落空亡。山啸呈宝，殿前作赋声摩空。', NULL, 0, 0, 1771384451);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('jin_003_shi_li_jian_feng', '石砺剑锋', NULL, NULL, NULL, 'c_91d1_661f_683c_5c40', NULL, NULL, '石砺剑锋，塞上封侯建功节。', NULL, 0, 0, 1771384451);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('jin_004_zhu_cang_yuan_hai', '珠藏渊海', NULL, NULL, NULL, 'c_91d1_661f_683c_5c40', NULL, NULL, '珠藏渊海，万人头上之英雄。', NULL, 0, 0, 1771384451);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('jin_005_hu_ju_long_pan', '虎踞龙蟠', NULL, NULL, NULL, 'c_91d1_661f_683c_5c40', NULL, NULL, '金果为龙虎之星，各得其用，而照守命宫者，佳。虎踞龙蟠，当朝之士。', NULL, 0, 0, 1771384451);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('jin_006_yun_jian_yue_zhuo', '云间鸑鷟', NULL, NULL, NULL, 'c_91d1_661f_683c_5c40', NULL, NULL, '云间鸑鷟，当为邸省之贤。午宫坐命，金气二星入宫坐命。', NULL, 0, 0, 1771384451);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('jin_007_tian_shang_qi_lin', '天上麒麟', NULL, NULL, NULL, 'c_91d1_661f_683c_5c40', NULL, NULL, '天上麒麟，定数东宫之贵。金果辰，木在卯，而在卯辰坐命者是。', NULL, 0, 0, 1771384452);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('jin_008_jin_guan_ding_cui', '金冠顶翠', NULL, NULL, NULL, 'c_91d1_661f_683c_5c40', NULL, NULL, '金冠顶翠，紫诰金花。金冠指金也，顶翠指木也，金宫会木以合此格也。', NULL, 0, 0, 1771384452);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('jin_009_yu_chu_kun_gang', '玉出昆冈', NULL, NULL, NULL, 'c_91d1_661f_683c_5c40', NULL, NULL, '玉出昆冈，罗帏绣幕。玉指金也，昆冈指土也，金土斗度逢空为合格。', NULL, 0, 0, 1771384452);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('jin_010_luan_yu_nan_xing', '鸾轝南幸', NULL, NULL, NULL, 'c_91d1_661f_683c_5c40', NULL, NULL, '金果拱日，在星房度。水南幸，人主之尊。', NULL, 0, 0, 1771384452);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('jin_011_feng_jia_bei_gui', '凤驾北归', NULL, NULL, NULL, 'c_91d1_661f_683c_5c40', NULL, NULL, '凤驾北归，帝王之象。', NULL, 0, 0, 1771384452);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('jin_012_yi_gan_jiu_shi', '移干就湿', NULL, NULL, NULL, 'c_91d1_661f_683c_5c40', NULL, NULL, '移干就湿，必主贫寒。', NULL, 0, 0, 1771384452);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('jin_013_jin_wu_cheng_rui', '金乌呈瑞', NULL, NULL, NULL, 'c_91d1_661f_683c_5c40', NULL, NULL, '金乌呈瑞，富贵两全。', NULL, 0, 0, 1771384452);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('jin_014_feng_yu_zuo_lin', '风雨作霖', NULL, NULL, NULL, 'c_91d1_661f_683c_5c40', NULL, NULL, '风雨作霖，有济世安民之略。果风毕雨，金水太阳躔毕箕度是也。', NULL, 0, 0, 1771384452);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('jin_015_lao_bang_han_zhu', '老蚌含珠', NULL, NULL, NULL, 'c_91d1_661f_683c_5c40', NULL, NULL, '老蚌含珠，乡闾望重。土金在亥子和辰巳宫，须金土为用神者。', NULL, 0, 0, 1771384452);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('jin_016_su_yue_liu_tian', '素月流天', NULL, NULL, NULL, 'c_91d1_661f_683c_5c40', NULL, NULL, '素月流天见金，而官居极品。', NULL, 0, 0, 1771384452);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('jin_017_jin_shui_bei_chi', '金水背驰', NULL, NULL, NULL, 'c_91d1_661f_683c_5c40', NULL, NULL, '金宝退留，用而无用，来而不来。愚格。', NULL, 0, 0, 1771384452);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('jin_018_jin_shui_fen_ming', '金水分明', NULL, NULL, NULL, 'c_91d1_661f_683c_5c40', NULL, NULL, '金水分明，水前金后，不宜混失退逆。贵。', NULL, 0, 0, 1771384452);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('jin_019_jin_shui_hui_yuan', '金水会垣', NULL, NULL, NULL, 'c_91d1_661f_683c_5c40', NULL, NULL, '金水会垣，水忌退于金后。水在金前，水受金生。贵。', NULL, 0, 0, 1771384452);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('jin_020_jin_han_shui_leng', '金寒水冷', NULL, NULL, NULL, 'c_91d1_661f_683c_5c40', NULL, NULL, '冬生金寒，水冷，未免孤寒之苦。', NULL, 0, 0, 1771384452);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('jin_021_jin_shui_wei_shi', '金水为仕', NULL, NULL, NULL, 'c_91d1_661f_683c_5c40', NULL, NULL, '金水躔奎壁，奎壁乃贵人星，文薮星。当云：五星连壁，五星聚奎，此乃文地。金躔参壁度，曰：金生水。水躔奎斗度曰：水生木，相生之德不混，为文人贵士也。', NULL, 0, 0, 1771384452);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('jin_022_jin_shui_hu_yuan', '金水互垣', NULL, NULL, NULL, 'c_91d1_661f_683c_5c40', NULL, NULL, '水居金垣，金入水垣，乃大吉也。', NULL, 0, 0, 1771384452);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('jin_023_jin_bei_qi_ma', '金孛骑马', NULL, NULL, NULL, 'c_91d1_661f_683c_5c40', NULL, NULL, '金孛入驿马桃花宫上，必放荡淫邪。', NULL, 0, 0, 1771384452);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('jin_024_jin_huo_yi_yuan', '金火易垣', NULL, NULL, NULL, 'c_91d1_661f_683c_5c40', NULL, NULL, '火金不可易垣。火不可入金垣，金不可入火垣，疑其相攻相克也。', NULL, 0, 0, 1771384452);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('jin_025_jin_shui_gong_cheng', '金水功成', NULL, NULL, NULL, 'c_91d1_661f_683c_5c40', NULL, NULL, '金水生助命位，益佐官禄，其功名可遂也。', NULL, 0, 0, 1771384452);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('jin_026_jin_bei_lin_shen', '金孛临身', NULL, NULL, NULL, 'c_91d1_661f_683c_5c40', NULL, NULL, '金孛匪宜临身。金孛同入命，则主淫冶好事。', NULL, 0, 0, 1771384452);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('jin_027_qing_ji_huo_yuan', '庆基获源', NULL, NULL, NULL, 'c_91d1_661f_683c_5c40', NULL, NULL, '庆金因为辰的意思。繇，因为的意思。', NULL, 0, 0, 1771384452);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('jin_028_jin_shui_hui_she', '金水会蛇', NULL, NULL, NULL, 'c_91d1_661f_683c_5c40', NULL, NULL, '金水凑于蛇穴，岂惟鹤发而休（金水会蛇在巳）', NULL, 0, 0, 1771384452);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('jin_029_jin_ju_wei_fen', '金居卫分', NULL, NULL, NULL, 'c_91d1_661f_683c_5c40', NULL, NULL, '金照卫而主寿（金在亥宫）。西方太白向卫分，益寿延年（金星居亥）。', NULL, 0, 0, 1771384452);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('jin_030_jin_yu_ying_huo', '金遇荧惑', NULL, NULL, NULL, 'c_91d1_661f_683c_5c40', NULL, NULL, '金照卫而主寿（金在亥宫），遇荧惑而夭天年（火必克金）', NULL, 0, 0, 1771384452);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('jin_031_jin_ju_kang_wei', '金居亢位', NULL, NULL, NULL, 'c_91d1_661f_683c_5c40', NULL, NULL, '欲问荣华，大抵抗金居亢位（金星在辰）', NULL, 0, 0, 1771384452);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('jin_032_jin_mu_zhao_shu_niu', '金木照于鼠牛', NULL, NULL, NULL, 'c_91d1_661f_683c_5c40', NULL, NULL, '先吉后凶，金木照于鼠牛之地（金木居子居丑）', NULL, 0, 0, 1771384452);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('jin_033_jin_cheng_huo_wei', '金乘火位', NULL, NULL, NULL, 'c_91d1_661f_683c_5c40', NULL, NULL, '金乘火位，其人少失双亲（金忌居卯戌宫）。金乘火位，在西北则轻。[戌土遇金]', NULL, 0, 0, 1771384452);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('jin_034_mu_jin_hui_tian', '木金会田', NULL, NULL, NULL, 'c_91d1_661f_683c_5c40', NULL, NULL, '多荣产业，木金会于田园（金木妙居田宅）', NULL, 0, 0, 1771384452);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('jin_035_san_ri_feng_jin', '三日逢金', NULL, NULL, NULL, 'c_91d1_661f_683c_5c40', NULL, NULL, '年年获福，皆因三日逢金（太阴泊处前后宫共四十五度，谓三日宫）', NULL, 0, 0, 1771384452);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('jin_036_tai_bai_shuang_tai', '太白双胎', NULL, NULL, NULL, 'c_91d1_661f_683c_5c40', NULL, NULL, '亥为登明，巳为太乙。', NULL, 0, 0, 1771384452);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('jin_037_huo_jin_zi_wei', '火金子位', NULL, NULL, NULL, 'c_91d1_661f_683c_5c40', NULL, NULL, '如此者非贫即夭。', NULL, 0, 0, 1771384452);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('jin_038_jin_shui_wen_zhi', '金水文智', NULL, NULL, NULL, 'c_91d1_661f_683c_5c40', NULL, NULL, '金水文辞为智巧。[金水在命]', NULL, 0, 0, 1771384452);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('jin_039_gang_rou_xiang_ji', '刚柔相济', NULL, NULL, NULL, 'c_91d1_661f_683c_5c40', NULL, NULL, '金曜本性最无情，见木刚柔须相济[金木宜同行]', NULL, 0, 0, 1771384452);
