INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('jin_060_huo_jin_shi_yue', '火金侍月', NULL, NULL, NULL, 'c_91d1_661f_683c_5c40', NULL, NULL, '火金侍月：火金为用神，临垣庙，夜生者妙。', NULL, 0, 0, 1771384453);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('jin_061_san_tai_he_ge', '三台合格', NULL, NULL, NULL, 'c_91d1_661f_683c_5c40', NULL, NULL, '三台合格：午巳卯宫得日金水同行。', NULL, 0, 0, 1771384453);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('jin_062_chu_gan_ru_kun', '出干入坤', NULL, NULL, NULL, 'c_91d1_661f_683c_5c40', NULL, NULL, '出干入坤。', NULL, 0, 0, 1771384453);
