INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('jin_064_jin_luo_tong_ke', '金罗同克', NULL, NULL, NULL, 'c_91d1_661f_683c_5c40', NULL, NULL, '金罗同克：金为用神则坏矣。', NULL, 0, 0, 1771384453);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('jin_065_qian_kun_pi_se', '乾坤否塞', NULL, NULL, NULL, 'c_91d1_661f_683c_5c40', NULL, NULL, '乾坤否塞：亥命金罗，申命土计。', NULL, 0, 0, 1771384453);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('jin_066_shan_ze_chen_mai', '山泽沉埋', NULL, NULL, NULL, 'c_91d1_661f_683c_5c40', NULL, NULL, '山泽沉埋。', NULL, 0, 0, 1771384453);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('jin_067_long_yue_tian_chi', '龙跃天池', NULL, NULL, NULL, 'c_91d1_661f_683c_5c40', NULL, NULL, '龙跃天池：亢进金龙立命，金亥从日月。', NULL, 0, 0, 1771384453);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('jin_068_cang_long_ru_jing', '苍龙入井', NULL, NULL, NULL, 'c_91d1_661f_683c_5c40', NULL, NULL, '苍龙入井。', NULL, 0, 0, 1771384453);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('jin_069_jin_ying_su_liu', '金莺宿柳', NULL, NULL, NULL, 'c_91d1_661f_683c_5c40', NULL, NULL, '金莺宿柳：金同命躔柳，近太阳尤妙。', NULL, 0, 0, 1771384453);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('jin_070_ba_sha_chao_tian', '八杀朝天', NULL, NULL, NULL, 'c_91d1_661f_683c_5c40', NULL, NULL, '八杀朝天：如戌命火，又未命土，或辰命金。此三星独占天门，得时为上。惟金火尤重，夜生显贵之人也。', NULL, 0, 0, 1771384453);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('jin_071_chang_geng_ru_ming', '长庚入命', NULL, NULL, NULL, 'c_91d1_661f_683c_5c40', NULL, NULL, '长庚入命：东有启明乃水星之象，西有长庚乃太白之象。昔李太白母梦长庚星入怀，盖月乃母道也，身之所从出也，夜生金月同在酉，乃合此格。李白母梦长庚入怀，觉而有忧虑，及生李白，命其名曰白，字太白，诗才冠天下，则知长庚入命，必主产不世之奇才也。', NULL, 0, 0, 1771384453);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('jin_072_bai_hu_dang_quan', '白虎当权', NULL, NULL, NULL, 'c_91d1_661f_683c_5c40', NULL, NULL, '秋生人见金星，在申酉安命，乃白虎当权。', NULL, 0, 0, 1771384453);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('jin_073_hu_ju_long_pan', '虎踞龙盘', NULL, NULL, NULL, 'c_91d1_661f_683c_5c40', NULL, NULL, '虎踞龙盘：木星乃东方之苍龙，金星乃西方之白虎，金在命木正照，夜生乃龙盘虎踞。金木同居于命，又为龙虎交驰，更在辰寅二宫坐命者尤妙。盖命宫居于子午，金星在酉，木星在卯，四正得之，正合此格。盖木为青龙在东方，金为白虎在西方，又在前四宫与后四宫拱照，岂得不为贵命。', NULL, 0, 0, 1771384453);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('jin_074_yue_hua_jin_que', '月华金阙', NULL, NULL, NULL, 'c_91d1_661f_683c_5c40', NULL, NULL, '月华金阙：金星在亥，与太阴同宫；金星在辰，与太阴同宫，皆谓之月华金阙。', NULL, 0, 0, 1771384453);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('jin_075_ri_hua_jin_que', '日华金阙', NULL, NULL, NULL, 'c_91d1_661f_683c_5c40', NULL, NULL, '若金星在亥、辰，与太阳同宫者，谓之日华金阙，主富贵。', NULL, 0, 0, 1771384453);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('jin_076_jin_ju_gan_wei', '金居干位', NULL, NULL, NULL, 'c_91d1_661f_683c_5c40', NULL, NULL, '金居干位：亥上乃西北，干位干宫为金，而金星亦居亥上，乃据格。未生与申生人，得金居干位最佳。盖未属井鬼，其分野则在秦；申属觜参，其分野则在晋，得金水正气，又与木日同居于亥，乃金居干位，若无火计罗孛入，皆为贵命。', NULL, 0, 0, 1771384453);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('jin_077_jin_qi_ren_ma', '金骑人马', NULL, NULL, NULL, 'c_91d1_661f_683c_5c40', NULL, NULL, '金骑人马：命立寅宫尾度，金星相会，又是寅年岁驾，谓曰金骑人马。我骑他，盖岁驾有侍从之义，主人禄享千钟，不可概以为不吉也。若罗星来犯，多有为人仆从，妻子早离。', NULL, 0, 0, 1771384453);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('jin_078_jin_shen_chi_ren', '金神持刃', NULL, NULL, NULL, 'c_91d1_661f_683c_5c40', NULL, NULL, '金神持刃：命立辰宫亢金度乃是，乙年刃在辰，却见金星亢度躔之，官封上将，镇守边庭，行限至午，而遇火临柳土，发财可比陶朱，若未限，见土躔井木生秋冬尚可，生于春夏，非夭则残疾。', NULL, 0, 0, 1771384453);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('jin_079_jin_xing_ru_dou', '金星入斗', NULL, NULL, NULL, 'c_91d1_661f_683c_5c40', NULL, NULL, '金星入斗：酉宫立命主，金飞入丑宫斗度，凡人命得此一星，主人才华，俊秀，早步青云，行寅限尾度，见火星，定主刑宪血疾，若在角度，反凶作吉，大主发福寿命延长。', NULL, 0, 0, 1771384453);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('jin_080_jin_mu_hai_shi', '金木亥室', NULL, NULL, NULL, 'c_91d1_661f_683c_5c40', NULL, NULL, '金木亥室：金星与木室相逢，官职荣迁至上公。', NULL, 0, 0, 1771384453);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('jin_081_jin_shui_xing_qiao', '金水性巧', NULL, NULL, NULL, 'c_91d1_661f_683c_5c40', NULL, NULL, '金水性巧：金水主人多精彩，自然巧劣心中藏。', NULL, 0, 0, 1771384453);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('jin_082_jin_bei_yin_lao', '金孛淫痨', NULL, NULL, NULL, 'c_91d1_661f_683c_5c40', NULL, NULL, '金孛淫痨：金孛交会为人淫，必主痨病及其身。', NULL, 0, 0, 1771384453);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('jin_083_jin_shui_bei_xian', '金水孛咸', NULL, NULL, NULL, 'c_91d1_661f_683c_5c40', NULL, NULL, '金水孛咸：妇人若见金水孛，三改嫁兮有何说。咸池带水与孛星，朝云暮雨情不歇。', NULL, 0, 0, 1771384453);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('jin_084_jin_shui_bei_mu', '金水孛沐', NULL, NULL, NULL, 'c_91d1_661f_683c_5c40', NULL, NULL, '金水孛沐：妇人金水孛星迎，身命同临性偏淫。更兼沐浴在其间，离居奔走落风尘。', NULL, 0, 0, 1771384453);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('jin_085_jin_xiao_tian_xie', '金销天蝎', NULL, NULL, NULL, 'c_91d1_661f_683c_5c40', NULL, NULL, '金销天蝎（房度）。断躔，忌。', NULL, 0, 0, 1771384453);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('jin_086_jin_xiao_bai_yang', '金销白羊', NULL, NULL, NULL, 'c_91d1_661f_683c_5c40', NULL, NULL, '金销白羊（奎度）。断躔，忌。', NULL, 0, 0, 1771384453);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('jin_087_chang_geng_chao_dou', '长庚朝斗', NULL, NULL, NULL, 'c_91d1_661f_683c_5c40', NULL, NULL, '金星丑宫斗木度。贵格。', NULL, 0, 0, 1771384453);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('jin_088_jin_mu_feng_long', '金木逢龙', NULL, NULL, NULL, 'c_91d1_661f_683c_5c40', NULL, NULL, '金木辰宫，贵格。', NULL, 0, 0, 1771384453);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('jin_089_shui_run_jin_ming', '水润金明', NULL, NULL, NULL, 'c_91d1_661f_683c_5c40', NULL, NULL, '水金辰宫，贵格。', NULL, 0, 0, 1771384453);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('jin_090_jin_hao_tai_chang', '金号太常', NULL, NULL, NULL, 'c_91d1_661f_683c_5c40', NULL, NULL, '金辰宫，贵格。', NULL, 0, 0, 1771384453);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('jin_091_jin_chan_gui_su', '金躔鬼宿', NULL, NULL, NULL, 'c_91d1_661f_683c_5c40', NULL, NULL, '金星未宫鬼宿。贵格。', NULL, 0, 0, 1771384454);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('jin_092_jin_xing_zhu_yue', '金星助月', NULL, NULL, NULL, 'c_91d1_661f_683c_5c40', NULL, NULL, '金星助月。', NULL, 0, 0, 1771384454);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('jin_093_jin_zhu_yue_hua', '金助月华', NULL, NULL, NULL, 'c_91d1_661f_683c_5c40', NULL, NULL, '金月酉宫。贵格。', NULL, 0, 0, 1771384454);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('jin_094_jin_zhang_ren_feng', '金掌刃锋', NULL, NULL, NULL, 'c_91d1_661f_683c_5c40', NULL, NULL, '金怕掌刃锋廉的耗符等煞，木命限人尤凶。', NULL, 0, 0, 1771384454);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('jin_095_lan_fu_xiu_zhen', '烂斧绣针', NULL, NULL, NULL, 'c_91d1_661f_683c_5c40', NULL, NULL, '金星落空谓之烂斧绣针，则是常用之物，又主利名有成。', NULL, 0, 0, 1771384454);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('jin_096_lian_jin_cheng_qi', '炼金成器', NULL, NULL, NULL, 'c_91d1_661f_683c_5c40', NULL, NULL, '春令之金不怕火罗，借火罗以温助，谓之炼金成器，变化气质。', NULL, 0, 0, 1771384454);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('jin_097_chun_jin_ji_shui', '春金忌水', NULL, NULL, NULL, 'c_91d1_661f_683c_5c40', NULL, NULL, '春令之金，不宜与水孛同行，春初生者，凝寒冻未退，无火日温之，极主贫寒。春月之金性柔体弱。', NULL, 0, 0, 1771384454);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('jin_098_shuo_shi_feng_yuan', '烁石逢源', NULL, NULL, NULL, 'c_91d1_661f_683c_5c40', NULL, NULL, '夏令之金，不宜生水，就赖水以制其刚，烁石逢源，主利名显达。', NULL, 0, 0, 1771384454);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('jin_099_xia_jin_feng_huo', '夏金逢火', NULL, NULL, NULL, 'c_91d1_661f_683c_5c40', NULL, NULL, '夏令罗火何以相逢，冬月如斯自能发福。', NULL, 0, 0, 1771384454);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('jin_100_jin_bai_shui_qing', '金白水清', NULL, NULL, NULL, 'c_91d1_661f_683c_5c40', NULL, NULL, '秋令之金乃白帝司权，金神用事不怕火罗而克，不喜土计而生，借水映色正此谓也。金白水清最喜秋生者，贵。若金水朝拱太阳，最高奇特。经曰：金坚而无火锻炼，终见凶顽。盖火尚杀伐，水尚澄清，文武皆沾，刚柔相济，名扬四海。', NULL, 0, 0, 1771384454);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('jin_101_dong_jin_xi_nuan', '冬金喜暖', NULL, NULL, NULL, 'c_91d1_661f_683c_5c40', NULL, NULL, '冬令之金，斯时寒凝冻结，昼喜日光而温之，夜喜火罗而照之，定主文职蒙恩，不宜与水孛相互作用，极主贫寒，水冷故也。最妙昼土逢阳，以温其土，可助其金，主威武之职。又逢火罗拱互降祥，正所谓金罗相会，阃外司权。', NULL, 0, 0, 1771384454);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('lt_001_he_bi_lian_zhu', '合璧连珠', NULL, NULL, NULL, 'c_7075_53f0_683c', NULL, NULL, '[原文] 夫日月五星皆会一决。日月则若璧合。五星则若球连。进退皆无盈缩之患。惟会丑者，九世一遇；会它次者，间世一遇。
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('lt_002_ri_yue_he_bi', '日月合璧', NULL, NULL, NULL, 'c_7075_53f0_683c', NULL, NULL, '[原文] 太阳与太阴同宫，或对照，或三合照是也。然须庙旺方为贵。日有中道，日有九行。中道者黄道也。九行者，青道二出黄道东，赤道二出黄道南，白道二出黄道西，黑道二出黄道北。分主八节，合乎四正四维。按阴阳中终之所交，则日行正当黄道。八行与中道而九。乾坤定位，则八位各得其正。及其寒暑相推，晦朔相易，则在南者变而居北，东者徙而为西。日行与岁运皆迁，月行随交限而变。日出入赤道二十四度，月出入黄道六度，故交于子正，则晦日之朝犹朔日之夕也，是日月皆不见。若合于午正，则晦日之晨，犹二日之昏也；是以月日皆见。盖其如合璧，当视子午正交。则人命在其中，可论其强弱。
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('lt_003_wu_xing_lian_zhu', '五星连珠', NULL, NULL, NULL, 'c_7075_53f0_683c', NULL, NULL, '[原文] 五星不必同宫，只得顺布，五位相续而不断者亦是。虚拱一位而命居其中者亦是。拱日门则是五星连珠；拱地户则是五星拱太微、拱紫微。所谓坐实不如拱虚，对照不如正照者是也；或顺乎两位而拱亦妙。五星运行各有次舍，及其相聚，却为难得，若得连珠尤妙。
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('lt_004_dou_niu_xiu_qi', '斗牛秀气', NULL, NULL, NULL, 'c_7075_53f0_683c', NULL, NULL, '[原文] 紫气，十一曜之最尊。清而贵文而美者也；丑位有斗牛二宿。乃二十八宿之始，金陵之气。盛于东南。龙泉之神光于牛斗，若紫气一星对照正照，丑上安命，特为奇异。日月五星初躔皆自星纪，故名星纪者，斗建之间也。
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('lt_005_wen_zhang_mi_fu', '文章秘府', NULL, NULL, NULL, 'c_7075_53f0_683c', NULL, NULL, '[原文] 日、月、木、金、水、气、罗三合对照，亥宫安命是也。亥有木星，主图书，乃文章秘府之星。主为人才学富足，见识超卓。福气亦厚。
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('lt_006_wu_xing_chao_dou', '五星朝斗', NULL, NULL, NULL, 'c_7075_53f0_683c', NULL, NULL, '[原文] 五星会于双鱼，则有卿相之象。若一星二星居于前后者，亦是日、月、木、金水五星同居双鱼宫是也。盖亥为天门，乃上帝之离宫，众星聚此，以拱北辰。是五星朝斗之宫也。
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('lt_007_bei_yu_dong_jing', '孛于东井', NULL, NULL, NULL, 'c_7075_53f0_683c', NULL, NULL, '[原文] 孛居未上。夜生人未上安命是也。贵而有权之命。古者太平之世，日不蚀，星不孛，则孛者，常顺于天，隐而不见。惟怒则为彗星，一见则众星失色。此星性猛，机变，威权。
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('lt_008_shou_xie_long_jiao', '首携龙角', NULL, NULL, NULL, 'c_7075_53f0_683c', NULL, NULL, '[原文] 角、亢二宿，为苍龙之角也。罗睺建首，乃天之神首。居辰之位，乃如龙之有首，而角、亢二宿左右扶之；以为之角矣。命居辰上而得罗睺，主为人荣显。
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('lt_009_ji_ju_long_wei', '计居龙尾', NULL, NULL, NULL, 'c_7075_53f0_683c', NULL, NULL, '[原文] 尾宿四星，为苍龙之尾宿也。计都星乃天之神尾，入寅之位乃如龙之有尾，而尾之四星又有辅翼则为真龙矣，凡此二格，皆主权高职重。
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('lt_010_yin_yang_lei_ju', '阴阳类聚', NULL, NULL, NULL, 'c_7075_53f0_683c', NULL, NULL, '[原文] 阴阳同居一处合为庙旺，得同类之吉星照身命者是也。《易》曰：水流湿火就燥，各从其类也。
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('lt_011_zhong_xing_gong_bei', '众星拱北', NULL, NULL, NULL, 'c_7075_53f0_683c', NULL, NULL, '[原文] 孔子曰：北辰居其所，而众星拱之。盖天之星运转不穷，而北辰一星不易其位，北辰所居，乃天之北极，子位是也。十一曜环居众位，而虚拱一子，却去子上安命是也。
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('lt_012_mao_tou_zhi_zheng', '旄头直争', NULL, NULL, NULL, 'c_7075_53f0_683c', NULL, NULL, '[原文] 罗睺乃天之神首。酉上有昴宿九天之旄头杀是也。安命在酉，而遇罗睺，加以一二恶星为祸最惨。
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('lt_013_chang_geng_ru_ming', '长庚入命', NULL, NULL, NULL, 'c_7075_53f0_683c', NULL, NULL, '[原文] 东有启明，乃水星之象。西有长庚，乃太白之象，昔李太白母梦长庚星入怀盖月乃母遘也。
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('lt_014_shen_yang_chu_xie', '神羊触邪', NULL, NULL, NULL, 'c_7075_53f0_683c', NULL, NULL, '[原文] 未上巨獬之分野，獬乃神羊之兽，遇恶则触。古者帝王置之殿庭，以警不忠。如孛在未，又在未上安命，纯无凶星者，为贵。
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('lt_015_ri_chu_fu_sang', '日出扶桑', NULL, NULL, NULL, 'c_7075_53f0_683c', NULL, NULL, '[原文] 卯为日门，乃旸谷扶桑之地，日坐于卯，无恶曜对照，而在卯上安命者，主贵。
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('lt_016_ji_xing_hao_feng', '箕星好风', NULL, NULL, NULL, 'c_7075_53f0_683c', NULL, NULL, '[原文] 日将出，清风发，群阴皆伏。是日出则生风；日入则无风。日在丑寅而丑寅坐命朝生，主有声名，如有恶星，则未免淫荡。
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('lt_017_bi_xing_hao_yu', '毕星好雨', NULL, NULL, NULL, 'c_7075_53f0_683c', NULL, NULL, '[原文] 诗云：月离于毕，俾滂沱矣。书云：星有好风，星有好雨。太阴躔毕度而在酉上安命是也。
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('lt_018_da_yue_dang_dou', '大月当斗', NULL, NULL, NULL, 'c_7075_53f0_683c', NULL, NULL, '[原文] 韩昌黎云：愈生之辰月宿斗。东坡亦身在摩羯宫故知月宿于斗，最出文人才子也。
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('lt_019_wu_shen_dang_quan', '五神当权', NULL, NULL, NULL, 'c_7075_53f0_683c', NULL, NULL, '[原文] 春生人见木星在寅卯安命，乃青龙用事；夏生人见火星在巳午安命，乃朱雀当权；秋生人见金星在申酉安命，乃白虎当权；冬生人见水星在亥子安命，乃玄武当权。四土星在辰戌丑未安命，乃勾陈得位。以上数者须是不背日月昼夜者妙。
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('lt_020_zuo_you_huan_gong', '左右环拱', NULL, NULL, NULL, 'c_7075_53f0_683c', NULL, NULL, '[原文] 凡人命宫若得五星左右环拱，无有不显达者，假如坐命在壁五度，木星在璧一度，则为左青龙；金星居璧九度，则为右白虎；火星在奎一度，则为前朱雀。水星居室十六度，则为后玄武。
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('lt_021_yue_fu_dou_bing', '月扶斗柄', NULL, NULL, NULL, 'c_7075_53f0_683c', NULL, NULL, '[原文] 凡月建所在，则是斗柄魁星之所指也。惟闰月斗柄斜指两辰之间。若太阴在月建之位者，乃合此格，一年有十二节候，斗杓随月建而转。
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('lt_022_feng_sheng_lang_ji', '风生浪击', NULL, NULL, NULL, 'c_7075_53f0_683c', NULL, NULL, '[原文] 凡人遇初八二十三日午时生者，皆狡猾凶恶，盖初八二十三日午时，乃月弦初生，而渐生于海，风生浪击之谓也。
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('lt_023_lu_ma_tong_xiang', '禄马同乡', NULL, NULL, NULL, 'c_7075_53f0_683c', NULL, NULL, '[原文] 禄元星与马元星照命者是也。书云：马元为贵为禄，仁元干配的无疑。寿元惟向纳音取，要照强宫与限随。凡人命最爱禄、马二元同在强宫以照命，未有不为显仕者。
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('lt_024_hu_ju_long_pan', '虎踞龙盘', NULL, NULL, NULL, 'c_7075_53f0_683c', NULL, NULL, '[原文] 木星乃东方之苍龙。金星乃西方之白虎。金在命木正照夜生乃龙盘虎踞。
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('lt_025_li_kan_jiao_hui', '离坎交会', NULL, NULL, NULL, 'c_7075_53f0_683c', NULL, NULL, '[原文] 水星禀北方坎宫之气。火星禀南方离宫之气。夜生人火星在命，水星正照，乃合此格。
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('lt_026_yin_yang_jiao_fu', '阴阳交辅', NULL, NULL, NULL, 'c_7075_53f0_683c', NULL, NULL, '[原文] 日为阳君，月为阴后，若与吉星夹照命宫者，合格也，若恶曜与日月同宫则非惟不能为福，而且生祸。
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('lt_027_ao_tou_du_bu', '鳌头独步', NULL, NULL, NULL, 'c_7075_53f0_683c', NULL, NULL, '[原文] 三春生人在寅、卯二宫安命，而寅、卯上见木星也，此得时、得位、得用，鳌头自当独步也。
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('lt_028_zi_xing_fu_zheng', '子行父政', NULL, NULL, NULL, 'c_7075_53f0_683c', NULL, NULL, '[原文] 太阳乃火之精，太阴乃水之副，故日为父，火为子。月为母，水为子也。且太阳之庙在午，太阳居之当然也。今则太阳却居子，火星却在午，又于午上安命，是父之政，子乃行之也。
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('lt_029_san_tai_fu_dou', '三台扶斗', NULL, NULL, NULL, 'c_7075_53f0_683c', NULL, NULL, '[原文] 斗在丑分，命若在丑，而得三台星同宫，乃此格也。若丑之前后三宫，皆有两星亦是。
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('lt_030_zi_wei_si_fu', '紫微四辅', NULL, NULL, NULL, 'c_7075_53f0_683c', NULL, NULL, '[原文] 旋转天轮，辰巳午未上有四吉星，巳午之间住命是也。辅星乃辅弼之象，得之者，当居宰辅。
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('lt_031_jing_shen_ju_zu', '精神俱足', NULL, NULL, NULL, 'c_7075_53f0_683c', NULL, NULL, '[原文] 天一生水，为人之精。地二生火，为人之神。水火顺受，人命得之为精神具足。
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('lt_032_yue_hua_jin_que', '月华金阙', NULL, NULL, NULL, 'c_7075_53f0_683c', NULL, NULL, '[原文] 金星在亥，与太阴同宫；金星在辰，与太阴同宫。皆谓之月华金阙；若金星在亥、辰与太阳同宫者，谓之日华金阙，二格皆主富贵。
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('lt_033_ri_zhong_jian_dou', '日中见斗', NULL, NULL, NULL, 'c_7075_53f0_683c', NULL, NULL, '[原文] 太阳与罗睺会合于未，而太阴又在未，此为日中见斗。太阳与太阴同宫，此为月朔可知，又与罗睺相会，此为日蚀可知。
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('lt_034_ming_ru_di_zhong', '明入地中', NULL, NULL, NULL, 'c_7075_53f0_683c', NULL, NULL, '[原文] 太阳至申酉而没。受罗睺所蚀，于申酉安命是也。太阳若星也，至申酉而西没，既已失于君位矣，坐命于此，已为无力，况被罗睺所蚀，其能自保乎。
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('lt_035_ming_chu_di_jin', '明出地晋', NULL, NULL, NULL, 'c_7075_53f0_683c', NULL, NULL, '[原文] 命宫在申，而太阳在寅；命宫在酉，而太阳在卯；命宫在戌，而太阳在辰，为明出地晋，此格须得金水辅太阳而行。
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('lt_036_mu_shang_shui_jing', '木上水井', NULL, NULL, NULL, 'c_7075_53f0_683c', NULL, NULL, '[原文] 水先入宫，木后入宫，或木星先入，水星后入。皆为井象。更得在东井未上，又在未上安命，必主道心员融，有常德以食天禄也。
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('lt_037_zhong_xing_huan_yue', '众星环月', NULL, NULL, NULL, 'c_7075_53f0_683c', NULL, NULL, '[原文] 夜生坤方五星环太阴，更在太阴宫住命者，合此格。太阴之行有九道，其行最疾，众星本不能环也。
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('lt_038_jin_ju_qian_wei', '金居乾位', NULL, NULL, NULL, 'c_7075_53f0_683c', NULL, NULL, '[原文] 亥上乃西北乾位乾宫为金，而金星亦居亥上，乃为此格。未生与申生人，得金居乾位最佳。
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('lt_039_shui_zhu_dong_nan', '水注东南', NULL, NULL, NULL, 'c_7075_53f0_683c', NULL, NULL, '[原文] 巽居巳位，东南之地也四方之水则皆会之于，虽北有溟浡，南有大海，西有流沙，而水之倾注则归于东海，以势不满于东南也。水星在巳，而木星与命宫在寅，乃合此格。
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('lt_040_chu_jiu_huan_xin', '除旧换新', NULL, NULL, NULL, 'c_7075_53f0_683c', NULL, NULL, '[原文] 月孛乃天上之彗星。有除旧换新之象所照之地，则有变易，更改其星，为扫帚，所以扫除尘秽，更新改旧。
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('lt_041_huo_shui_wei_ji', '火水未济', NULL, NULL, NULL, 'c_7075_53f0_683c', NULL, NULL, '[原文] 火先入宫，水后入宫，同居一宫以照命者是也。盖火自上炎，水自下注，相违而不相向。安得能和而能济。故易曰：未济，男之穷也。格中带此者，主贫贱。
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('mu_001_ri_bian_hong_xing', '日边红杏', NULL, NULL, NULL, 'c_6728_661f_683c_5c40', NULL, NULL, '日邊紅杏，早占鰲頭。[紅杏者木星也，木為官、恩、命、令等用者，與太陽同行。]', NULL, 0, 0, 1771384456);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('mu_002_xue_ya_han_mei', '雪压寒梅', NULL, NULL, NULL, 'c_6728_661f_683c_5c40', NULL, NULL, '雪壓寒梅，終身餓莩。[寒梅者木星也，木水同躔，夜生冬值，倘或在子丑地及水宮、水度者亦是。]', NULL, 0, 0, 1771384456);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('mu_003_qi_cha_han_mei', '齐插寒梅', NULL, NULL, NULL, 'c_6728_661f_683c_5c40', NULL, NULL, '命立子宮度，木為福德、財帛二主，飛入命位，是乃謂財福剋命，不可概以木打寶瓶論也。若木遇形剋之星，財福減半；倘命主衰弱，反不能勝矣。經云：安命子宮，木入齊瓶。若非李郭之榮，必有陶朱之富。', NULL, 0, 0, 1771384456);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('mu_004_xiang_yang_hua_mu', '向阳花木', NULL, NULL, NULL, 'c_6728_661f_683c_5c40', NULL, NULL, '向陽花木，三台八座之榮。[木為官恩命令順行，見日晝生春夏者佳。]', NULL, 0, 0, 1771384456);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('mu_005_zhao_shui_mei_hua', '照水梅花', NULL, NULL, NULL, 'c_6728_661f_683c_5c40', NULL, NULL, '照水梅花，萬軸五車之學。[木在巳申，冬生逢晝，為美。]', NULL, 0, 0, 1771384456);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('mu_006_chun_sheng_yang_liu', '春生杨柳', NULL, NULL, NULL, 'c_6728_661f_683c_5c40', NULL, NULL, '春生楊柳，合作妓娼。[楊柳喻木也，春生木躔箕度]', NULL, 0, 0, 1771384456);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('mu_007_qiu_ri_wu_tong', '秋日梧桐', NULL, NULL, NULL, 'c_6728_661f_683c_5c40', NULL, NULL, '秋日梧桐，堪為僧道。[梧桐喻木也，秋生木遇孤寡羊刃。]', NULL, 0, 0, 1771384456);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('mu_008_yue_zhong_xian_gui', '月中仙桂', NULL, NULL, NULL, 'c_6728_661f_683c_5c40', NULL, NULL, '月中仙桂，少年平步青雲。[木躔心、張、危、畢月度，或秋生木月同宮亦是]', NULL, 0, 0, 1771384456);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('mu_009_ri_shai_hua_zhi', '日晒花枝', NULL, NULL, NULL, 'c_6728_661f_683c_5c40', NULL, NULL, '日曬花枝，壯歲趨朝丹闕。[木臨星虛房、昴日度、或春生木日同宮皆是。]', NULL, 0, 0, 1771384456);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('mu_010_mei_shao_heng_yue', '梅梢横月', NULL, NULL, NULL, 'c_6728_661f_683c_5c40', NULL, NULL, '梅梢橫月，簞瓢陋巷之人。[木月會子宮，生於秋冬。]', NULL, 0, 0, 1771384456);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('mu_011_liu_xu_sui_feng', '柳絮随风', NULL, NULL, NULL, 'c_6728_661f_683c_5c40', NULL, NULL, '柳絮隨風，萍水他鄉之客。[木星秉令躔箕度，或在巳宮巽地。]', NULL, 0, 0, 1771384456);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('mu_012_yu_zhou_hua_can', '雨骤花残', NULL, NULL, NULL, 'c_6728_661f_683c_5c40', NULL, NULL, '雨驟花殘，窮愁萬種。[春生木躔畢度，蓋畢宿好雨故也。]', NULL, 0, 0, 1771384456);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('mu_013_feng_yao_ye_luo', '风摇叶落', NULL, NULL, NULL, 'c_6728_661f_683c_5c40', NULL, NULL, '風搖葉落，辛苦無閑。[秋生木躔箕度，蓋箕好風故耳。]', NULL, 0, 0, 1771384456);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('mu_014_an_che_pu_lun', '安车蒲轮', NULL, NULL, NULL, 'c_6728_661f_683c_5c40', NULL, NULL, '安車蒲輪，翰苑編修集撰。[安車即木也，木會日與馬元同宮。]', NULL, 0, 0, 1771384456);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('mu_015_mei_ying_heng_chuang', '梅影横窗', NULL, NULL, NULL, 'c_6728_661f_683c_5c40', NULL, NULL, '梅影橫窗，一生清貴。[梅影喻木也，木月冬生，同在壁府。]', NULL, 0, 0, 1771384456);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('mu_016_tao_hua_lang_nuan', '桃花浪暖', NULL, NULL, NULL, 'c_6728_661f_683c_5c40', NULL, NULL, '桃花浪暖，昭代文章。[桃花譬木也，木水會命，在奎度尢妙。]', NULL, 0, 0, 1771384456);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('mu_017_hua_li_ting_can', '花里停骖', NULL, NULL, NULL, 'c_6728_661f_683c_5c40', NULL, NULL, '花裏停驂，封侯列仕。[木為命、恩、令同太陰與馬元在張、心、危、畢月度。]', NULL, 0, 0, 1771384456);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('mu_018_dan_gui_piao_xiang', '丹桂飘香', NULL, NULL, NULL, 'c_6728_661f_683c_5c40', NULL, NULL, '丹桂飄香，或貧寒尤當食祿。[秋木為用神，在巽巳地。]', NULL, 0, 0, 1771384456);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('mu_019_li_hua_dai_yu', '梨花带雨', NULL, NULL, NULL, 'c_6728_661f_683c_5c40', NULL, NULL, '梨花帶雨，縱富貴亦主重夫。[女人之命，春木為夫元、命主，在酉申畢度。]', NULL, 0, 0, 1771384456);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('mu_020_nan_zhi_xiang_nuan', '南枝向暖', NULL, NULL, NULL, 'c_6728_661f_683c_5c40', NULL, NULL, '南枝向煖，相國經邦。[南乃午宮，枝言木也，冬木為用神，喜居午上，或太陽合格。]', NULL, 0, 0, 1771384456);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('mu_021_san_tai_he_ge', '三台合格', NULL, NULL, NULL, 'c_6728_661f_683c_5c40', NULL, NULL, '或木星在午[木為歲星君象也，得金水巳未，或寅戌二方拱合，亦曰三奇，此木所主，惟春夏得用，秋冬不取。]双鱼按：三台合格的格局不只一种，此处之论木星成格。木星在午，对于狮子座来说是不利的，但是午狮子之位在上天紫微垣乃帝座鶉火之位，而木星又为岁星，太岁乃君象，木星临午则有君临帝座的意味。此格貌似于"南枝向暖"格局有些相似之处，但是区别是：1南枝向暖是冬木为用神，喜居午上，取调侯的意思。而木星的三台合格是春夏得用，秋冬不取2木星三台合格须有金水的夹拱辅弼。而南枝向暖无其它附加条件。', NULL, 0, 0, 1771384456);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('mu_022_mu_qi_fu_shen', '木气扶身', NULL, NULL, NULL, 'c_6728_661f_683c_5c40', NULL, NULL, '木氣星同太陰，必賢達者，或老成功而能設策、處公道之人也。', NULL, 0, 0, 1771384456);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('mu_023_mu_qi_jia_ming', '木气夹命', NULL, NULL, NULL, 'c_6728_661f_683c_5c40', NULL, NULL, '木氣拱身夾命，必有壽而聰明。[木氣清高善曜、文學之星，守命臨身，必主聰明清秀，或泊孤寡主有壽孤剋也。]', NULL, 0, 0, 1771384456);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('mu_024_mu_qi_guan_ming', '木气贯命', NULL, NULL, NULL, 'c_6728_661f_683c_5c40', NULL, NULL, '木氣貫命，多於林下逍遙。[木氣二星貫守命度，多宜林下。]', NULL, 0, 0, 1771384456);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('mu_025_mu_xing_zhao_lin', '木星照临', NULL, NULL, NULL, 'c_6728_661f_683c_5c40', NULL, NULL, '木星照臨，主人技藝學、術亦是文人才士。', NULL, 0, 0, 1771384456);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('mu_026_mu_lin_zhen_yuan', '木临真垣', NULL, NULL, NULL, 'c_6728_661f_683c_5c40', NULL, NULL, '木臨寅亥是真垣，精神百倍（木居寅亥）。《玉衡经》：木德臨垣，剛毅而懷惻隱。[木主仁好善]', NULL, 0, 0, 1771384456);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('mu_027_sun_ji_ji_ren', '损己济人', NULL, NULL, NULL, 'c_6728_661f_683c_5c40', NULL, NULL, '捐自己之財以濟人，必是木同紫氣(木主剛毅，氣為慈祥)', NULL, 0, 0, 1771384456);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('mu_028_mu_ru_qin_zhou', '木入秦州', NULL, NULL, NULL, 'c_6728_661f_683c_5c40', NULL, NULL, '木入秦州旺鬼，而初歸巨蟹(木星在未)。《元通赋》：歲居蟹鬼，而順將逆相。（木入秦川）。双鱼按：巨蟹、鬼宿的分野在秦，木到巨蟹入旺，成贵格。', NULL, 0, 0, 1771384456);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('mu_029_sui_ju_xie_gui', '岁居蟹鬼', NULL, NULL, NULL, 'c_6728_661f_683c_5c40', NULL, NULL, '同"木入秦州"。歲居蟹鬼，而順將逆相。（木入秦川）', NULL, 0, 0, 1771384456);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('mu_030_shui_mu_chong_lin', '水木重临', NULL, NULL, NULL, 'c_6728_661f_683c_5c40', NULL, NULL, '水木重臨，文章秀麗.[水木相逢]', NULL, 0, 0, 1771384456);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('mu_031_mu_xian_kan_wei', '木嫌坎位', NULL, NULL, NULL, 'c_6728_661f_683c_5c40', NULL, NULL, '木嫌坎位. [木打寶瓶]。双鱼按：坎位即是宝瓶座，宝瓶属土，木星临此为怒地，不吉。若宝瓶立命，木为福德、财帛主，福财克命反吉。', NULL, 0, 0, 1771384456);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('mu_032_mu_da_bao_ping', '木打宝瓶', NULL, NULL, NULL, 'c_6728_661f_683c_5c40', NULL, NULL, '同"木嫌坎位"。木打寶瓶，木星临宝瓶（子宫）为怒地，不吉。', NULL, 0, 0, 1771384456);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('mu_033_mu_luo_dong_jing', '木罗东井', NULL, NULL, NULL, 'c_6728_661f_683c_5c40', NULL, NULL, '木臨東井，要神首以加臨. [木羅同未井度]', NULL, 0, 0, 1771384456);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('mu_034_mu_zheng_dong_fang', '木正东方', NULL, NULL, NULL, 'c_6728_661f_683c_5c40', NULL, NULL, '仁慈聰俊，木正東方. [木星得位]。双鱼按：东方为木旺之地，卯天蝎是木帝旺之乡，木星临此是背中反旺之格，贵。', NULL, 0, 0, 1771384456);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('mu_035_mu_yang_zhao_qian', '木阳照迁', NULL, NULL, NULL, 'c_6728_661f_683c_5c40', NULL, NULL, '人事和同遷移，木得陽臨照. [木日同遷移]', NULL, 0, 0, 1771384457);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('mu_036_mu_de_lin_yuan', '木德临垣', NULL, NULL, NULL, 'c_6728_661f_683c_5c40', NULL, NULL, '同"木临真垣"。《玉衡经》：木德臨垣，剛毅而懷惻隱。[木主仁好善]。《躔度赋》：木臨寅亥是真垣，精神百倍（木居寅亥）', NULL, 0, 0, 1771384457);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('mu_037_nv_chan_mu_xian', '女缠木限', NULL, NULL, NULL, 'c_6728_661f_683c_5c40', NULL, NULL, '女命限到木躔防夫害子[木氣乃孤剋之宿]。双鱼按：男人限到金月则招妻纳妾，女人限到木缠，不利于姻缘仔细，因为木气常带孤劫等不利姻缘的神煞。', NULL, 0, 0, 1771384457);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('mu_038_tu_mu_xi_zheng', '土木息争', NULL, NULL, NULL, 'c_6728_661f_683c_5c40', NULL, NULL, '木土偏愛陽宮，雖戰而無損[土木在寅]。', NULL, 0, 0, 1771384457);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('mu_039_mu_bu_nan_ben', '木不南奔', NULL, NULL, NULL, 'c_6728_661f_683c_5c40', NULL, NULL, '木居獅子，居官不能享官[木不南奔午宮也]', NULL, 0, 0, 1771384457);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('mu_040_mu_luo_hui_she', '木罗会舍', NULL, NULL, NULL, 'c_6728_661f_683c_5c40', NULL, NULL, '木羅會舍，喜入寅宮[木入垣羅入廟]。《十一曜定格》：木為用神冬春生，躔廟旺宮佳。', NULL, 0, 0, 1771384457);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('mu_041_shui_fan_mu_piao', '水泛木漂', NULL, NULL, NULL, 'c_6728_661f_683c_5c40', NULL, NULL, '無根之木遇惡水，而飄泛東西[木躔金度或與金同，夏月水勢盛反被漂流]', NULL, 0, 0, 1771384457);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('mu_042_han_mu_xiang_yang', '寒木向阳', NULL, NULL, NULL, 'c_6728_661f_683c_5c40', NULL, NULL, '冬春之木見日，則謂向陽', NULL, 0, 0, 1771384457);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('mu_043_qiu_shui_nan_zi', '秋水难滋', NULL, NULL, NULL, 'c_6728_661f_683c_5c40', NULL, NULL, '秋水非滋木之時[秋木凋零，不能足水之滋]', NULL, 0, 0, 1771384457);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('mu_044_mu_tu_xiang_an', '木土相安', NULL, NULL, NULL, 'c_6728_661f_683c_5c40', NULL, NULL, '土在子，木在午，似有衝而無害[子命]。双鱼按：子命土为命主，木为福元，看似对冲，实则福元克命，无害也。', NULL, 0, 0, 1771384457);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('mu_045_lin_quan_gao_zhi', '林泉高致', NULL, NULL, NULL, 'c_6728_661f_683c_5c40', NULL, NULL, '如逢木氣，山間林下作生涯[月逢木氣]', NULL, 0, 0, 1771384457);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('mu_046_mu_qi_fan_yue', '木气犯月', NULL, NULL, NULL, 'c_6728_661f_683c_5c40', NULL, NULL, '木氣犯月,命居於鶉火之位。双鱼按：鶉火之位为狮子，立命在此，木气为难，伴月则安身傍难，忌格。', NULL, 0, 0, 1771384457);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('mu_047_yi_xing_ban_yue', '一星伴月', NULL, NULL, NULL, 'c_6728_661f_683c_5c40', NULL, NULL, '木星伴月朝東井[未命]。双鱼按：一星伴月的格局不只此一种，《李橙问答》中说一星是指水星，但是在《广寒赋》中却列出了四种一星伴月格，除土星外，其他四星皆可成一星伴月之格：凡金星伴月以躔亢[辰命]；水星伴月而入軫[巳命]；火星伴月向南斗[丑命]；木星伴月朝東井[未命]。雖然一星伴月，自古宜有,不如眾星朗朗,孤月獨明。', NULL, 0, 0, 1771384457);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('mu_048_tian_di_kai_ming', '天地开明', NULL, NULL, NULL, 'c_6728_661f_683c_5c40', NULL, NULL, '天地開明[水居申，木居亥，又於此二宮安命，是有開明之義，而得羅計在子午攔截為合格，若羅計在辰戌中攔為破格。]', NULL, 0, 0, 1771384457);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('mu_049_shan_ze_tong_qi', '山泽通气', NULL, NULL, NULL, 'c_6728_661f_683c_5c40', NULL, NULL, '山澤通氣[艮為山，木星居之，兌為澤，金星居之，二星得所，為通氣。]', NULL, 0, 0, 1771384457);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('mu_050_shan_ze_chen_mai', '山泽沉埋', NULL, NULL, NULL, 'c_6728_661f_683c_5c40', NULL, NULL, '山澤沉埋[金入寅而體絕，木至酉而受傷，乃沉埋之象。]（双鱼按："木"原文作"水"，疑误，故改之）', NULL, 0, 0, 1771384457);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('mu_051_jie_mu_xing_zai', '劫木兴灾', NULL, NULL, NULL, 'c_6728_661f_683c_5c40', NULL, NULL, '劫木為災難避。[木星如梃杖之屬，掌劫亦能害人命限，切忌逢之，寅亥二宮，犯劫是也。]', NULL, 0, 0, 1771384457);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('mu_052_long_hu_feng_yun_hui', '龙虎风云会', NULL, NULL, NULL, 'c_6728_661f_683c_5c40', NULL, NULL, '官魁夾命帶龍虎，則廊廟良材。[如命安在卯，而木金化為官魁，在寅辰歸垣夾命，乃龍虎慶會風雲，必主圭璋美玉。]', NULL, 0, 0, 1771384457);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('mu_053_mu_xing_sheng_dian', '木星升殿', NULL, NULL, NULL, 'c_6728_661f_683c_5c40', NULL, NULL, '木躔角斗奎井四宿。', NULL, 0, 0, 1771384457);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('mu_054_mu_yue_qing_gui', '木月清贵', NULL, NULL, NULL, 'c_6728_661f_683c_5c40', NULL, NULL, '弦朢夜生合格，月晦、寒天不取。', NULL, 0, 0, 1771384457);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('mu_055_mu_huo_wen_ming', '木火文明', NULL, NULL, NULL, 'c_6728_661f_683c_5c40', NULL, NULL, '冬春月生，無分晝夜為妙。', NULL, 0, 0, 1771384457);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('mu_056_qing_long_fu_yan', '青龙扶砚', NULL, NULL, NULL, 'c_6728_661f_683c_5c40', NULL, NULL, '寅卯月生，木日同宮。木為青龍星。', NULL, 0, 0, 1771384457);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('mu_057_mu_ru_jin_xiang', '木入金乡', NULL, NULL, NULL, 'c_6728_661f_683c_5c40', NULL, NULL, '木在辰酉二宮。忌格。', NULL, 0, 0, 1771384457);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('mu_058_mu_ru_tu_shi', '木入土室', NULL, NULL, NULL, 'c_6728_661f_683c_5c40', NULL, NULL, '木居子丑二宮。忌格。', NULL, 0, 0, 1771384457);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('mu_059_mu_tu_xiang_ke', '木土相剋', NULL, NULL, NULL, 'c_6728_661f_683c_5c40', NULL, NULL, '木遇土而剋。', NULL, 0, 0, 1771384457);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('mu_060_mu_bei_fu_yin', '木孛符印', NULL, NULL, NULL, 'c_6728_661f_683c_5c40', NULL, NULL, '木為用神，臨廟旺吉。冬生無力。', NULL, 0, 0, 1771384457);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('mu_061_mu_bi_yang_guang', '木蔽阳光', NULL, NULL, NULL, 'c_6728_661f_683c_5c40', NULL, NULL, '晝生忌木氣掩，夜生宜火羅助。', NULL, 0, 0, 1771384457);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('mu_062_mu_qi_lian_zhi', '木气联枝', NULL, NULL, NULL, 'c_6728_661f_683c_5c40', NULL, NULL, '木氣孛在寅亥，命宮官祿合格。', NULL, 0, 0, 1771384457);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('mu_063_hu_xiao_yuan_yin', '虎啸猿吟', NULL, NULL, NULL, 'c_6728_661f_683c_5c40', NULL, NULL, '木尾火觜，亥命大貴，巳命大富。', NULL, 0, 0, 1771384457);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('mu_064_hu_ju_long_pan', '虎踞龙盘', NULL, NULL, NULL, 'c_6728_661f_683c_5c40', NULL, NULL, '木星乃東方之蒼龍，金星乃西方之白虎，金在命木正照，夜生乃龍盤虎踞。⊙金木同居於命，又為龍虎交馳，更在辰寅二宮坐命者尤妙。⊙命宮居於子午，金星在酉，木星在卯，四正得之，正合此格。蓋木為青龍在東方，金為白虎在西方，又在前四宮與後四宮拱照，豈得不為貴命。', NULL, 0, 0, 1771384457);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('mu_065_qing_long_dang_quan', '青龙当权', NULL, NULL, NULL, 'c_6728_661f_683c_5c40', NULL, NULL, '春生人見木星，在寅卯安命，乃青龍用事。', NULL, 0, 0, 1771384457);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('mu_066_ao_tou_du_bu', '鳌头独步', NULL, NULL, NULL, 'c_6728_661f_683c_5c40', NULL, NULL, '三春生人在寅卯二宮安命，而寅卯上見木星也，此得時得位得用鰲頭，自當獨步也，前格所謂青龍當權，亦此義耳。', NULL, 0, 0, 1771384457);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('mu_067_mu_shang_shui_jing', '木上水井', NULL, NULL, NULL, 'c_6728_661f_683c_5c40', NULL, NULL, '水先入宮，木後入宮，或木星先入，水星後入，皆為井象，更得在東井未上，又在未上安命，必主道心員融，有常德以食天祿也。⊙井居其所而不遷，地之德也，而木居水上，有養而不窮之義。⊙或人命得木同居於未，而水星對照於亥，此亦得木上水井格。蓋亥居下而有井之象也，然在天之井，則異於是，以井而居河漢之中，其為度，則三十，視其他度數最長，半次實沈、半次鶉首，在實沈者，水為樂宮，在鶉首者，水為入廟，此亦養而不窮之義。', NULL, 0, 0, 1771384457);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('mu_068_jiao_mu_duan_chan', '角木断躔', NULL, NULL, NULL, 'c_6728_661f_683c_5c40', NULL, NULL, '立命丑宮斗木度，土躔斗度，行限辰宮，木星又躔角度，故曰：角木斷躔，必然主死於非命，定因親族相累，禍起於蕭牆。又云：木度立命，見木帶煞，乃自家殺自家。', NULL, 0, 0, 1771384457);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('mu_069_ji_feng_dou_kou', '箕风斗口', NULL, NULL, NULL, 'c_6728_661f_683c_5c40', NULL, NULL, '命立亥，行寅限而遇木星在箕度，箕星好風原，主風搖葉落，行限重見箕度，或斗度，故曰：箕風斗口見之，家破身亡，不然水火而終。', NULL, 0, 0, 1771384457);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('mu_070_jin_mu_hai_shi', '金木亥室', NULL, NULL, NULL, 'c_6728_661f_683c_5c40', NULL, NULL, '金星與木室相逢，官職榮遷至上公。', NULL, 0, 0, 1771384457);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('mu_080_jiao_ji_feng_chang', '脚疾风肠', NULL, NULL, NULL, 'c_6728_661f_683c_5c40', NULL, NULL, '木星為病有一方，必主腳疾及風腸。', NULL, 0, 0, 1771384457);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('mu_081_mu_ji_tong_yin', '木计同寅', NULL, NULL, NULL, 'c_6728_661f_683c_5c40', NULL, NULL, '分布得經、俱是十二宮星辰得局貴格。寅宫：木计同寅。', NULL, 0, 0, 1771384457);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('mu_082_jin_mu_feng_long', '金木逢龙', NULL, NULL, NULL, 'c_6728_661f_683c_5c40', NULL, NULL, '分布得經、俱是十二宮星辰得局貴格。辰宮：金木逢龍。', NULL, 0, 0, 1771384457);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('mu_083_mu_chan_jiao_dao', '木躔角道', NULL, NULL, NULL, 'c_6728_661f_683c_5c40', NULL, NULL, '分布得經、俱是十二宮星辰得局貴格。辰宮：木躔角道。', NULL, 0, 0, 1771384457);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('mu_084_mu_tu_xiang_hui', '木土相会', NULL, NULL, NULL, 'c_6728_661f_683c_5c40', NULL, NULL, '分布得經、俱是十二宮星辰得局貴格。申宮：木土相會。', NULL, 0, 0, 1771384457);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('mu_085_jin_mu_cheng_wang', '金木乘旺', NULL, NULL, NULL, 'c_6728_661f_683c_5c40', NULL, NULL, '分布得經、俱是十二宮星辰得局貴格。亥宫：金木乘旺。', NULL, 0, 0, 1771384457);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('mu_086_mu_lin_ying_shi', '木临营室', NULL, NULL, NULL, 'c_6728_661f_683c_5c40', NULL, NULL, '分布得經、俱是十二宮星辰得局貴格。亥宫：木臨熒室。', NULL, 0, 0, 1771384458);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('mu_087_mu_ji_feng_yu', '木计逢鱼', NULL, NULL, NULL, 'c_6728_661f_683c_5c40', NULL, NULL, '分布得經、俱是十二宮星辰得局貴格。亥宫：木计逢鱼。', NULL, 0, 0, 1771384458);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('mu_088_mu_chu_jin_long', '木触金龙', NULL, NULL, NULL, 'c_6728_661f_683c_5c40', NULL, NULL, '木在辰宫，参考"木入金乡"。', NULL, 0, 0, 1771384458);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('mu_089_chun_mu_ge', '纯木格', NULL, NULL, NULL, 'c_6728_661f_683c_5c40', NULL, NULL, '天元星最要緊，或守命得令相資，或是身命主聰明，加生旺貴祿為奇。[天元者，如甲天元屬木，而木星守命，或命度純木尤奇。]', NULL, 0, 0, 1771384458);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('mu_090_mu_tu_hui_ji', '木土会吉', NULL, NULL, NULL, 'c_6728_661f_683c_5c40', NULL, NULL, '四木安命，木土同度得躔，又得生旺財帛擁進，更財福二宮有吉星扶為上格。[四木者，斗木獬、奎木狼、井木犴、角木蛟之類。]', NULL, 0, 0, 1771384458);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('mu_091_ru_miao_tui_xing', '入庙退行', NULL, NULL, NULL, 'c_6728_661f_683c_5c40', NULL, NULL, '木躔斗入廟而退行，得失相伴。', NULL, 0, 0, 1771384458);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('mu_092_ku_zhi_bai_ye', '枯枝败叶', NULL, NULL, NULL, 'c_6728_661f_683c_5c40', NULL, NULL, '木星落空謂之枯枝敗葉。', NULL, 0, 0, 1771384458);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('mu_093_zhuo_xiao_cheng_cai', '琢削成材', NULL, NULL, NULL, 'c_6728_661f_683c_5c40', NULL, NULL, '木星落空謂之枯枝敗葉，如金會則琢削成材。', NULL, 0, 0, 1771384458);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('mu_094_fen_zhe_hui_mie', '焚折灰灭', NULL, NULL, NULL, 'c_6728_661f_683c_5c40', NULL, NULL, '木星落空謂之枯枝敗葉，火會則焚折灰滅。', NULL, 0, 0, 1771384458);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('mu_095_piao_cha_fan_fa', '漂槎泛筏', NULL, NULL, NULL, 'c_6728_661f_683c_5c40', NULL, NULL, '木星落空謂之枯枝敗葉，水會則漂槎泛筏，不免流蕩。', NULL, 0, 0, 1771384458);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('mu_096_ri_lie_mu_jiao', '日烈木焦', NULL, NULL, NULL, 'c_6728_661f_683c_5c40', NULL, NULL, '夏末秋初之木，斯時氣脈虛矣，晝生忌躔四火之度。又不宜與太陽交互，蓋是日烈木焦不足論也。', NULL, 0, 0, 1771384458);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('mu_097_shang_xia_ji_run', '上下济润', NULL, NULL, NULL, 'c_6728_661f_683c_5c40', NULL, NULL, '夏末秋初之木，斯時氣脈虛矣，晝生忌躔四火之度。又不宜與太陽交互，蓋是日烈木焦不足論也。晝生木躔四水之度而與太陽交光，此是上下濟潤不可以木焦日烈而論，乃水之秀麗，枝葉繁茂，精神富貴。', NULL, 0, 0, 1771384458);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('mu_098_bu_zhan_xian_kui', '布占先魁', NULL, NULL, NULL, 'c_6728_661f_683c_5c40', NULL, NULL, '冬令之木，斯時萬物蕭疏。如晝生與太陽交光謂之，日邊紅杏、布占先魁，遇此造化，豈不美哉！兼能有幹，文才清高。', NULL, 0, 0, 1771384458);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('mu_099_han_gu_hui_chun', '寒谷回春', NULL, NULL, NULL, 'c_6728_661f_683c_5c40', NULL, NULL, '冬令之木，斯時萬物蕭疏。如日生遇火羅，謂之寒谷回春，富貴雙全。如無太陽火羅同宮，得生巳午未之時，借日光霽，冰霜凍解，猶可舒暢，或木躔四火之度，又與太陽交輝，可作十全之福也。', NULL, 0, 0, 1771384458);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('mu_100_shui_bei_dong_zhe', '水孛冻折', NULL, NULL, NULL, 'c_6728_661f_683c_5c40', NULL, NULL, '冬令之木，斯時萬物蕭疏。如遇夜生木躔四土之度，又逢水孛凍折，窮之極矣。', NULL, 0, 0, 1771384458);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('ssby_001_qi_cha_sai_mei', '齐插塞梅', NULL, NULL, NULL, 'c_5341_4e09_8865_9057', NULL, NULL, '[原文] 命立子宫度，木为福德财帛二主飞入命位。是乃谓财福克命。不可概以木打宝瓶论也。若木遇刑克之星，财福减半；倘命主衰弱，反不能胜矣。《经》云：安命子宫，木入齐瓶。若非李郭之荣，必有陶朱之富。
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('ssby_002_jiao_mu_duan_chan', '角木断躔', NULL, NULL, NULL, 'c_5341_4e09_8865_9057', NULL, NULL, '[原文] 立命丑宫斗木度。土躔斗度。行限辰宫，木星又躔角度，故曰角木断躔。必然主死于非命。定因亲族相累，祸起于萧墙。又云：木度立命，见木带煞，乃自家杀自家。
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('ssby_003_jin_qi_ren_ma', '金骑人马', NULL, NULL, NULL, 'c_5341_4e09_8865_9057', NULL, NULL, '[原文] 命立寅宫尾度。金星相会。又是寅年岁驾。谓曰金骑人马。我骑他，盖岁驾有侍从之义，主人禄享千锺，不可概以为不吉也。若罗星来犯，多有为人仆从，妻子早离。
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('ssby_004_shui_huo_xiang_xing', '水火相刑', NULL, NULL, NULL, 'c_5341_4e09_8865_9057', NULL, NULL, '[原文] 歌曰：
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('ssby_005_jin_shen_chi_ren', '金神持刃', NULL, NULL, NULL, 'c_5341_4e09_8865_9057', NULL, NULL, '[原文] 命立辰宫亢金度。乃是乙年刃在辰。却见金星亢度躔之，官封上将。镇守边庭，行限至午，而遇火临柳土，发财可比陶朱。若未限，见土躔井木，生秋冬尚可，生于春夏，非夭则残疾。
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('ssby_006_yuan_wu_dang_tai', '元武当台', NULL, NULL, NULL, 'c_5341_4e09_8865_9057', NULL, NULL, '[原文] 歌云：
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('ssby_007_zi_cheng_fu_wei', '子承父位', NULL, NULL, NULL, 'c_5341_4e09_8865_9057', NULL, NULL, '[原文] 午宫星度立命，火星入命以占父位，太阳飞入卯宫房度，卯乃子位，父居之必主父子不和。兄弟失伦，行限见木，非犯刑而死，定主恶疾而亡。
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('ssby_008_yue_ming_dou_fu', '月明斗府', NULL, NULL, NULL, 'c_5341_4e09_8865_9057', NULL, NULL, '[原文] 命立未宫井木度。生于十五至十八日夜令之际，月在丑宫斗度，故谓月明斗府，必主文章冠世。如月坐斗六度，或寅宫斗度，谓之月扶斗柄。官居翰苑。三台八座，女命值此，得两国之封。限行酉宫，土在胃度限至，必主恶死。
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('ssby_009_xiang_yun_peng_yue', '祥云捧月', NULL, NULL, NULL, 'c_5341_4e09_8865_9057', NULL, NULL, '[原文] 立命未宫，生于初八至十五；月离海岛，光明渐著，夜生在丑酉戌未四宫而气月同行，月在气后三度，气在月前三度是也，主人丰姿清丽，文雅过人，若会罗星一混，谓之二奴夹主，定应中途孤苦。贫穷无托。孛又飞来同度，此凶中变吉，吉则难量，行限酉宫见土，富贵。戌宫限见难计。家破人离，流年土孛冲照水火灾厄。
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('ssby_010_tai_yi_bao_chan', '太乙抱蟾', NULL, NULL, NULL, 'c_5341_4e09_8865_9057', NULL, NULL, '[原文] 歌云：
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('ssby_011_shui_shi_zao_xing', '水士遭刑', NULL, NULL, NULL, 'c_5341_4e09_8865_9057', NULL, NULL, '[原文] 歌云：
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('ssby_012_jin_xing_ru_dou', '金星入斗', NULL, NULL, NULL, 'c_5341_4e09_8865_9057', NULL, NULL, '[原文] 酉宫立命，主金飞入丑宫斗度，凡人命得此一星主人才华俊秀，早步青云。行寅限尾度见火星，定主刑宪血疾，若在箕度，反凶作吉。大主发福寿命延长。
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('shui_001_jun_chen_qing_hui', '君臣庆会', NULL, NULL, NULL, 'c_6c34_661f_683c_5c40', NULL, NULL, '君臣庆会，钟鸣鼎食之家。金水为官福恩令命元，朝辅太阳者是。', NULL, 0, 0, 1771384458);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('shui_002_shui_cou_tian_chi', '水凑天池', NULL, NULL, NULL, 'c_6c34_661f_683c_5c40', NULL, NULL, '水凑天池，三峡词源之豪迈。春生水为用神，躔壁度，以亥为天池。', NULL, 0, 0, 1771384458);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('shui_003_gan_xuan_kun_zhuan', '干旋坤转', NULL, NULL, NULL, 'c_6c34_661f_683c_5c40', NULL, NULL, '干旋坤转，有庆之人。', NULL, 0, 0, 1771384458);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('shui_004_luan_yu_nan_xing', '鸾轝南幸', NULL, NULL, NULL, 'c_6c34_661f_683c_5c40', NULL, NULL, '金果拱日，在星房度。水南幸，人主之尊。', NULL, 0, 0, 1771384458);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('shui_005_feng_jia_bei_gui', '凤驾北归', NULL, NULL, NULL, 'c_6c34_661f_683c_5c40', NULL, NULL, '凤驾北归，帝王之象。', NULL, 0, 0, 1771384458);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('shui_006_yi_gan_jiu_shi', '移干就湿', NULL, NULL, NULL, 'c_6c34_661f_683c_5c40', NULL, NULL, '移干就湿，必主贫寒。', NULL, 0, 0, 1771384458);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('shui_007_feng_yu_zuo_lin', '风雨作霖', NULL, NULL, NULL, 'c_6c34_661f_683c_5c40', NULL, NULL, '风雨作霖，有济世安民之略。果风毕雨，金水太阳躔毕箕度是也。', NULL, 0, 0, 1771384458);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('shui_008_jin_shui_bei_chi', '金水背驰', NULL, NULL, NULL, 'c_6c34_661f_683c_5c40', NULL, NULL, '金宝退留，用而无用，来而不来。愚格。', NULL, 0, 0, 1771384458);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('shui_009_jin_shui_fen_ming', '金水分明', NULL, NULL, NULL, 'c_6c34_661f_683c_5c40', NULL, NULL, '金水分明，水前金后，不宜混失退逆。贵。', NULL, 0, 0, 1771384458);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('shui_010_jin_shui_hui_yuan', '金水会垣', NULL, NULL, NULL, 'c_6c34_661f_683c_5c40', NULL, NULL, '金水会垣，水忌退于金后。水在金前，水受金生。贵。', NULL, 0, 0, 1771384458);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('shui_011_jin_han_shui_leng', '金寒水冷', NULL, NULL, NULL, 'c_6c34_661f_683c_5c40', NULL, NULL, '冬生金寒，水冷，未免孤寒之苦。', NULL, 0, 0, 1771384458);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('shui_012_jin_shui_wei_shi', '金水为仕', NULL, NULL, NULL, 'c_6c34_661f_683c_5c40', NULL, NULL, '金水躔奎壁，无例外必为仕人。金水躔奎壁，奎壁乃贵人星，文薮星。当云：五星连壁，五星聚奎，此乃文地。金躔参壁度，曰：金生水。水躔奎斗度曰：水生木，相生之德不混，为文人贵士也。', NULL, 0, 0, 1771384458);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('shui_013_jin_shui_hu_yuan', '金水互垣', NULL, NULL, NULL, 'c_6c34_661f_683c_5c40', NULL, NULL, '金居互济，终身而有庆。水居金垣，金入水垣，乃大吉也。', NULL, 0, 0, 1771384458);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('shui_014_jin_shui_gong_cheng', '金水功成', NULL, NULL, NULL, 'c_6c34_661f_683c_5c40', NULL, NULL, '金水生命中位，益佐官禄，其功名可遂也。', NULL, 0, 0, 1771384458);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('shui_015_shui_an_tian_zhai', '水暗田宅', NULL, NULL, NULL, 'c_6c34_661f_683c_5c40', NULL, NULL, '水星本无定性，飘流之星也，况又化暗守田宅，主祖业无依。', NULL, 0, 0, 1771384458);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('shui_016_shui_zhi_si_shen', '水至巳申', NULL, NULL, NULL, 'c_6c34_661f_683c_5c40', NULL, NULL, '水至巳申诚入局，气象俱新（水在巳申）', NULL, 0, 0, 1771384459);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('shui_017_shui_ri_tong_zhou', '水日同周', NULL, NULL, NULL, 'c_6c34_661f_683c_5c40', NULL, NULL, '水日合星张之位，陛庭补衮赞皇明（水日在午）', NULL, 0, 0, 1771384459);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('shui_018_jin_shui_hui_she', '金水会蛇', NULL, NULL, NULL, 'c_6c34_661f_683c_5c40', NULL, NULL, '金水凑于蛇穴，岂惟鹤发而休（金水会蛇在巳）', NULL, 0, 0, 1771384459);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('shui_019_shui_liu_an_chun_wei', '水流鹌鹑尾', NULL, NULL, NULL, 'c_6c34_661f_683c_5c40', NULL, NULL, '水流鹌鹑尾，巧计千般（水星在巳）', NULL, 0, 0, 1771384459);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('shui_020_shui_hui_ji_du', '水会计都', NULL, NULL, NULL, 'c_6c34_661f_683c_5c40', NULL, NULL, '掠他人之物以利己，盖缘水会计都（水主智谋，计好狡猾）', NULL, 0, 0, 1771384459);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('shui_021_shui_huo_xiang_zhan', '水火相战', NULL, NULL, NULL, 'c_6c34_661f_683c_5c40', NULL, NULL, '一身迍蹇，火星怕与水星交战', NULL, 0, 0, 1771384459);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('shui_022_shui_liu_yang_zhou', '水流扬州', NULL, NULL, NULL, 'c_6c34_661f_683c_5c40', NULL, NULL, '眉颦常不足，只嫌水到扬州（水星在丑宫）', NULL, 0, 0, 1771384459);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('shui_023_shui_lin_shuang_nv', '水临双女', NULL, NULL, NULL, 'c_6c34_661f_683c_5c40', NULL, NULL, '给谏功臣，定是水临双女（水星在巳）', NULL, 0, 0, 1771384459);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('shui_024_jin_huo_tong_cai', '金火同财', NULL, NULL, NULL, 'c_6c34_661f_683c_5c40', NULL, NULL, '少失资财，金火同居财位（金火忌守财宫）', NULL, 0, 0, 1771384459);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('shui_025_shui_huo_ju_tian', '水火居田', NULL, NULL, NULL, 'c_6c34_661f_683c_5c40', NULL, NULL, '水火并居田宅，破家荡产（水火忌居田宅）。祖财困辱田宅，火被水来侵。', NULL, 0, 0, 1771384459);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('shui_026_shui_su_lin_cai', '水宿临财', NULL, NULL, NULL, 'c_6c34_661f_683c_5c40', NULL, NULL, '财帛衰退，被水宿加临（水星忌居财宫）', NULL, 0, 0, 1771384459);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('shui_027_shui_mu_chong_lin', '水木重临', NULL, NULL, NULL, 'c_6c34_661f_683c_5c40', NULL, NULL, '水木重临，文章秀丽。[水木相逢]', NULL, 0, 0, 1771384459);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('shui_028_shui_jin_tong_chou', '水金同丑', NULL, NULL, NULL, 'c_6c34_661f_683c_5c40', NULL, NULL, '泉枯牛荒，须凭金曜生成。[水金同丑]', NULL, 0, 0, 1771384459);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('shui_029_shui_bei_tong_du', '水孛同度', NULL, NULL, NULL, 'c_6c34_661f_683c_5c40', NULL, NULL, '水孛同度性偏淫。[水孛照身命]', NULL, 0, 0, 1771384459);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('shui_030_chao_yun_mu_yu', '朝云暮雨', NULL, NULL, NULL, 'c_6c34_661f_683c_5c40', NULL, NULL, '朝云，暮雨，水孛俱坐迁移。[水孛淫荡星也]', NULL, 0, 0, 1771384459);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('shui_031_shui_su_ju_qiang', '水宿居强', NULL, NULL, NULL, 'c_6c34_661f_683c_5c40', NULL, NULL, '水星无心常好动，向昼楚晋郑为强[水宜巳申辰宫]', NULL, 0, 0, 1771384459);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('shui_032_shui_xing_shou_ming', '水星守命', NULL, NULL, NULL, 'c_6c34_661f_683c_5c40', NULL, NULL, '水如守命，多学少成。[水主智刚无常性]', NULL, 0, 0, 1771384459);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('shui_033_shui_bei_tian_cai', '水孛田财', NULL, NULL, NULL, 'c_6c34_661f_683c_5c40', NULL, NULL, '水孛如守田财，难招祖业[水孛漂流无定]', NULL, 0, 0, 1771384459);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('shui_034_shui_ji_xiang_xing', '水计相刑', NULL, NULL, NULL, 'c_6c34_661f_683c_5c40', NULL, NULL, '水计相刑，怕居巳位[巳乃三刑之地]', NULL, 0, 0, 1771384459);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('shui_035_shui_ru_yin_gong', '水入寅宫', NULL, NULL, NULL, 'c_6c34_661f_683c_5c40', NULL, NULL, '水入寅宫，喉喉壅塞[寅乃喉舌之府]', NULL, 0, 0, 1771384459);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('shui_036_tu_hun_shui_zhuo', '土混水浊', NULL, NULL, NULL, 'c_6c34_661f_683c_5c40', NULL, NULL, '土混水而致浊[ 冬水冰结土混不清]', NULL, 0, 0, 1771384459);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('shui_037_shui_fan_tu_beng', '水泛土崩', NULL, NULL, NULL, 'c_6c34_661f_683c_5c40', NULL, NULL, '受制之土见猛水，而崩溃四出[ 春夏生物之土乃为受制，遇水反崩溃]', NULL, 0, 0, 1771384459);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('shui_038_xia_shui_ku_he', '夏水枯涸', NULL, NULL, NULL, 'c_6c34_661f_683c_5c40', NULL, NULL, '六月之水最怕火日枯涸[六月水主辅阳，反为不美]', NULL, 0, 0, 1771384459);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('shui_039_dong_shui_nan_ben', '冬水南奔', NULL, NULL, NULL, 'c_6c34_661f_683c_5c40', NULL, NULL, '冬水喜于南奔，戌火忌于发露[居娄宿则吉，微弱宜藏]', NULL, 0, 0, 1771384459);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('shui_040_shui_dong_jin_han', '水冻金寒', NULL, NULL, NULL, 'c_6c34_661f_683c_5c40', NULL, NULL, '水冻金寒，纵相生而不发', NULL, 0, 0, 1771384459);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('shui_041_shui_run_zao_tu', '水润燥土', NULL, NULL, NULL, 'c_6c34_661f_683c_5c40', NULL, NULL, '刚燥之土遇水滋润[ 夏土干燥，爱水滋润]', NULL, 0, 0, 1771384459);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('shui_042_chen_xing_ju_yuan', '辰星居垣', NULL, NULL, NULL, 'c_6c34_661f_683c_5c40', NULL, NULL, '辰星居垣，水星入本垣为贵格。', NULL, 0, 0, 1771384459);
