INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('shui_044_shui_han_chan_po', '水涵蟾魄', NULL, NULL, NULL, 'c_6c34_661f_683c_5c40', NULL, NULL, '水涵蟾魄：月寒水冷何益，望前，望后尤佳。', NULL, 0, 0, 1771384459);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('shui_045_jin_shui_xiang_han', '金水相涵', NULL, NULL, NULL, 'c_6c34_661f_683c_5c40', NULL, NULL, '金水相涵：冬生金寒水冷，余时昼夜皆吉。', NULL, 0, 0, 1771384459);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('shui_046_yuan_wu_chi_jing', '元武持旌', NULL, NULL, NULL, 'c_6c34_661f_683c_5c40', NULL, NULL, '元为元武星。水星持旌为贵格。', NULL, 0, 0, 1771384459);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('shui_047_shui_ju_tu_shi', '水居土室', NULL, NULL, NULL, 'c_6c34_661f_683c_5c40', NULL, NULL, '水居土室：水在子丑二宫。', NULL, 0, 0, 1771384459);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('shui_048_shui_cheng_huo_wei', '水乘火位', NULL, NULL, NULL, 'c_6c34_661f_683c_5c40', NULL, NULL, '水乘火位，水星入火位，水火相济。', NULL, 0, 0, 1771384459);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('shui_049_jin_shui_cong_yang', '金水从阳', NULL, NULL, NULL, 'c_6c34_661f_683c_5c40', NULL, NULL, '金水从阳：金水掌吉神，居垣殿，昼生者奇。', NULL, 0, 0, 1771384459);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('shui_050_san_tai_he_ge', '三台合格', NULL, NULL, NULL, 'c_6c34_661f_683c_5c40', NULL, NULL, '三台合格：午巳卯宫得日金水同行。', NULL, 0, 0, 1771384459);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('shui_051_tian_di_kai_ming', '天地开明', NULL, NULL, NULL, 'c_6c34_661f_683c_5c40', NULL, NULL, '天地开明：水申木亥，命安申亥，罗计子午。', NULL, 0, 0, 1771384459);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('shui_052_shui_huo_ji_ji', '水火既济', NULL, NULL, NULL, 'c_6c34_661f_683c_5c40', NULL, NULL, '水火既济：水子火午，命坐子午。', NULL, 0, 0, 1771384459);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('shui_053_feng_lei_gu_wu', '风雷鼓舞', NULL, NULL, NULL, 'c_6c34_661f_683c_5c40', NULL, NULL, '风雷鼓舞：水巳火卯，命辰合格。', NULL, 0, 0, 1771384459);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('shui_054_feng_lei_xiang_bo', '风雷相薄', NULL, NULL, NULL, 'c_6c34_661f_683c_5c40', NULL, NULL, '风雷相薄，水火交激之象。', NULL, 0, 0, 1771384459);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('shui_055_shui_huo_xiang_she', '水火相射', NULL, NULL, NULL, 'c_6c34_661f_683c_5c40', NULL, NULL, '水火相射：水午火子，或木卯戌，或火巳申。', NULL, 0, 0, 1771384459);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('shui_056_yu_yuan_shou_kun', '玉猿守昆', NULL, NULL, NULL, 'c_6c34_661f_683c_5c40', NULL, NULL, '玉猿守昆：水躔参度会日，命安水度者贵。', NULL, 0, 0, 1771384459);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('shui_057_shuang_yu_xi_shui', '双鱼戏水', NULL, NULL, NULL, 'c_6c34_661f_683c_5c40', NULL, NULL, '双鱼戏水，水星入亥宫为贵格。', NULL, 0, 0, 1771384460);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('shui_058_yu_nv_chang_e', '玉女嫦娥', NULL, NULL, NULL, 'c_6c34_661f_683c_5c40', NULL, NULL, '玉女嫦娥：水轸月张，命箕主贵，女貌倾国。', NULL, 0, 0, 1771384460);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('shui_059_yuan_wu_dang_quan', '元武当权', NULL, NULL, NULL, 'c_6c34_661f_683c_5c40', NULL, NULL, '冬生人见水星，在亥子安命，乃元武当权。元武当台：歌云：巳宫立命水在轸，元武升垣诸杀顺。又兼一点太白来，富贵绵绵应不降低。若还中限见土星，重整门庭兴进永。', NULL, 0, 0, 1771384460);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('shui_060_li_kan_jiao_hui', '离坎交会', NULL, NULL, NULL, 'c_6c34_661f_683c_5c40', NULL, NULL, '离坎交会：水星禀北方坎宫之气，火星禀南方离宫之气，夜生人火星在命中，水星正照，乃合此格，此格最主为人气概精神，法能剸裁繁剧，禄位优厚。若水火二星同守命宫，则是煎熬星矣，反主灾祸。', NULL, 0, 0, 1771384460);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('shui_061_zi_xing_fu_zheng', '子行父政', NULL, NULL, NULL, 'c_6c34_661f_683c_5c40', NULL, NULL, '子行父政：太阴为水之副，月为母，水为子也。太阴之庙在未，太阴居之当然也，今则太阴却居丑，水星却在未，又于未上安命，亦亦行行父政之说也。此格主人艰难于始，逸乐于终，以其干蛊之早也。谓且父之创制，子当继之，父之德政，予当行之。此谓人有贤子而继父志，不亦善乎！', NULL, 0, 0, 1771384460);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('shui_062_shui_zhu_dong_nan', '水注东南', NULL, NULL, NULL, 'c_6c34_661f_683c_5c40', NULL, NULL, '水注东南：巽居巳位东南之地也，四方之水则皆会之于箕，虽北有溟浡，南有大海，西有流沙，而水之倾注则归于东海，以势不满于东南也。水星在巳，而木星与命宫在寅，乃合此格。酉生人与寅生人，得水星在巳，木星与命在寅是也。盖寅属尾，尾巴在燕，酉属毕，毕分在赵，独得水正气，而流入于巽，是水有所归，况与木命同在寅，或木命与寅生同在酉，得水日在四正之宫，则又为水归地户格。', NULL, 0, 0, 1771384460);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('shui_063_huo_shui_wei_ji', '火水未济', NULL, NULL, NULL, 'c_6c34_661f_683c_5c40', NULL, NULL, '火水未济：火先入宫，水后入宫，同居一宫，以照命者是也。盖火自上炎，水自下注，相违而不相向，安得能和而能济。曰：未济男之穷也。格中带此者，主贫贱。此系忌格。', NULL, 0, 0, 1771384460);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('shui_064_shui_huo_ji_ji_2', '水火既济', NULL, NULL, NULL, 'c_6c34_661f_683c_5c40', NULL, NULL, '水火既济：水先入宫，火后入宫，同居一位以照命者是也。盖水性润下，火性炎上，上下相得，而不相违，切嫌一二凶星入侵，则反生祸。更若水星为宫主，为命主，为禄主，则福最厚，富贵双全之命也。', NULL, 0, 0, 1771384460);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('shui_065_shui_huo_xiang_xing', '水火相刑', NULL, NULL, NULL, 'c_6c34_661f_683c_5c40', NULL, NULL, '水火相刑：歌曰：命立卯宫在房度，生于夏令主炎库。行限午宫见水星，水入午宫宜柳土。反凶为吉福无边，金玉争光敌国富。若教脱水鬼门关，五十三四归泉路。', NULL, 0, 0, 1771384460);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('shui_066_shui_tu_zao_xing', '水土遭刑', NULL, NULL, NULL, 'c_6c34_661f_683c_5c40', NULL, NULL, '水木遭刑：歌云：申宫立命水为主，限戌恩金在奎度。金木相刑恩受制，反吉为凶横死鬼。限行亥宫见土星，土入江湖壁水度。也教富贵一时来，一十五年花锦丽。脱土半百危十五，溺死官刑骨肉忌。行奎度，在火宫则金受制，行亥见土，则能生金，金生水则发，到危则被土克。', NULL, 0, 0, 1771384460);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('shui_067_jin_shui_xing_qiao', '金水性巧', NULL, NULL, NULL, 'c_6c34_661f_683c_5c40', NULL, NULL, '金水巧：金水主人多精彩，自然巧劣心中藏。', NULL, 0, 0, 1771384460);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('shui_068_shui_bei_chang_you', '水孛倡优', NULL, NULL, NULL, 'c_6c34_661f_683c_5c40', NULL, NULL, '水孛倡优：女逢水孛是娼优，不是娼优缁素娘。', NULL, 0, 0, 1771384460);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('shui_069_jin_shui_bei_xian', '金水孛咸', NULL, NULL, NULL, 'c_6c34_661f_683c_5c40', NULL, NULL, '金池孛咸：妇人若见金水孛，三改嫁兮有何说。咸池带水与孛星，朝云暮雨情不歇。', NULL, 0, 0, 1771384460);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('shui_070_jin_shui_bei_mu', '金水孛沐', NULL, NULL, NULL, 'c_6c34_661f_683c_5c40', NULL, NULL, '金水孛沐：妇人金水孛星迎，身命同临性偏偏淫。更兼沐浴在其间，离居奔走落风尘。', NULL, 0, 0, 1771384460);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('shui_071_shui_piao_yang_jiao', '水漂羊角', NULL, NULL, NULL, 'c_6c34_661f_683c_5c40', NULL, NULL, '水漂羊角（娄度）。断躔，忌。', NULL, 0, 0, 1771384460);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('shui_072_shui_liu_ju_xie', '水流巨蟹', NULL, NULL, NULL, 'c_6c34_661f_683c_5c40', NULL, NULL, '水流巨蟹（柳度）。断躔，忌。', NULL, 0, 0, 1771384460);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('shui_073_shui_qing_bao_ping', '水清宝瓶', NULL, NULL, NULL, 'c_6c34_661f_683c_5c40', NULL, NULL, '子宫：水清宝瓶，得局贵格。', NULL, 0, 0, 1771384460);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('shui_074_shui_run_jin_ming', '水润金明', NULL, NULL, NULL, 'c_6c34_661f_683c_5c40', NULL, NULL, '水金辰宫，贵格。', NULL, 0, 0, 1771384460);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('shui_075_ri_shui_cheng_wang', '日水乘旺', NULL, NULL, NULL, 'c_6c34_661f_683c_5c40', NULL, NULL, '日水巳宫，贵格。', NULL, 0, 0, 1771384460);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('shui_076_shui_yang_xiang_hui', '水阳相会', NULL, NULL, NULL, 'c_6c34_661f_683c_5c40', NULL, NULL, '水太阳在午宫。贵格。', NULL, 0, 0, 1771384460);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('shui_077_shui_ming_rong_xian', '水名荣显', NULL, NULL, NULL, 'c_6c34_661f_683c_5c40', NULL, NULL, '水午宫。贵格。', NULL, 0, 0, 1771384460);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('shui_078_shui_bei_fu_chen', '水孛浮沉', NULL, NULL, NULL, 'c_6c34_661f_683c_5c40', NULL, NULL, '水孛怕尾，忌带浮沉亡劫的耗等煞，火命限人尤畏。', NULL, 0, 0, 1771384460);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('shui_079_chang_jiang_hao_dang', '长江浩荡', NULL, NULL, NULL, 'c_6c34_661f_683c_5c40', NULL, NULL, '水星落空谓之长江浩荡，退败无余。', NULL, 0, 0, 1771384460);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('shui_080_hong_shui_tao_tian', '洪水滔天', NULL, NULL, NULL, 'c_6c34_661f_683c_5c40', NULL, NULL, '水星落空谓之长江浩荡，退败无余，如金会则洪水滔天，常有不测之灾。', NULL, 0, 0, 1771384460);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('shui_081_guang_ji_cheng_che', '光霁澄彻', NULL, NULL, NULL, 'c_6c34_661f_683c_5c40', NULL, NULL, '春令之水，斯时冰霜冻冷，借木气火罗温之，自能变化，昼生水孛太阳同行名曰"光霁澄彻"谓之"冰霜冻解"心宇清吉，作事整肃，政令威仪，当主台省扬名。', NULL, 0, 0, 1771384460);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('shui_082_chun_shui_ji_jin', '春水忌金', NULL, NULL, NULL, 'c_6c34_661f_683c_5c40', NULL, NULL, '春令之水，斯时冰霜冻冷，所忌金星相互作用。昼生为妙，夜生贫寒。', NULL, 0, 0, 1771384460);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('shui_083_xia_shui_feng_di', '夏水逢堤', NULL, NULL, NULL, 'c_6c34_661f_683c_5c40', NULL, NULL, '经云：水盛而无土，堤防，遂归虚浊。若有土旺不以为倒限，论反主名利发达。惟六月之水最', NULL, 0, 0, 1771384460);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('shui_084_qiu_shui_qing_yuan', '秋水清源', NULL, NULL, NULL, 'c_6c34_661f_683c_5c40', NULL, NULL, '秋令之水，七八月间既济万物，不宜受克，既能借土堤防而不泛滥，又能润土，结实万物，清源可爱，富贵荣华。若水受克泄者，皆水之气脉虚矣，却不为福。', NULL, 0, 0, 1771384460);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('shui_085_dong_shui_san_ling', '冬水三令', NULL, NULL, NULL, 'c_6c34_661f_683c_5c40', NULL, NULL, '斯时点水成冰，冻结寒滞，不能变化。得火为上令，得土为次令，得太阳佐之方可言令也。', NULL, 0, 0, 1771384460);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('shui_086_dong_jin_wu_yi', '冬金无义', NULL, NULL, NULL, 'c_6c34_661f_683c_5c40', NULL, NULL, '然冬水自得其时，不用金生，使之见金，反为无义，乃曰：道义相忘唯喜在于火木也。', NULL, 0, 0, 1771384460);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('tu_001_gou_chen_zhen_dian', '勾陈镇殿', NULL, NULL, NULL, 'c_571f_661f_683c_5c40', NULL, NULL, '勾陈镇殿，珮玉腰金。土掌官恩，命令，同太阳躔虚星房，昴日度。', NULL, 0, 0, 1771384460);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('tu_002_shan_xiao_cheng_bao', '山啸呈宝', NULL, NULL, NULL, 'c_571f_661f_683c_5c40', NULL, NULL, '山啸呈宝，殿前作赋声摩空。土星落空谓之土陷山崩，必主退败可畏，如有恶星降夹逼迫，多见气蹙噎吃之疾，必主倒限。如金会谓之山啸呈宝，又主名利发达。', NULL, 0, 0, 1771384461);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('tu_003_shi_li_jian_feng', '石砺剑锋', NULL, NULL, NULL, 'c_571f_661f_683c_5c40', NULL, NULL, '石砺剑锋，塞上封侯建功节。', NULL, 0, 0, 1771384461);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('tu_004_zhu_cang_yuan_hai', '珠藏渊海', NULL, NULL, NULL, 'c_571f_661f_683c_5c40', NULL, NULL, '珠藏渊海，万人头上之英雄。', NULL, 0, 0, 1771384461);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('tu_005_lao_bang_han_zhu', '老蚌含珠', NULL, NULL, NULL, 'c_571f_661f_683c_5c40', NULL, NULL, '老蚌含珠，乡闾望重。土金在亥子和辰巳宫，须金土为用神者。', NULL, 0, 0, 1771384461);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('tu_006_han_yun_chu_xiu', '寒云出岫', NULL, NULL, NULL, 'c_571f_661f_683c_5c40', NULL, NULL, '寒云出岫遇土，而身隐空山。', NULL, 0, 0, 1771384461);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('tu_007_tu_bei_chan', '土孛掺', NULL, NULL, NULL, 'c_571f_661f_683c_5c40', NULL, NULL, '土孛相战，星辰崩溃。愚格。', NULL, 0, 0, 1771384461);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('tu_008_zhou_huo_ye_tu', '昼火夜土', NULL, NULL, NULL, 'c_571f_661f_683c_5c40', NULL, NULL, '火土分昼夜之忌。昼生忌火罗，夜生忌土计。', NULL, 0, 0, 1771384461);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('tu_009_ye_tu_jie_yue', '夜土截月', NULL, NULL, NULL, 'c_571f_661f_683c_5c40', NULL, NULL, '土化刑，夜生嫌与月同行。', NULL, 0, 0, 1771384461);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('tu_010_tu_bei_po_guan', '土孛破官', NULL, NULL, NULL, 'c_571f_661f_683c_5c40', NULL, NULL, '土孛破官，徒向仕途奔走。官星被土孛伤破，可为医，卜，吏，书，卒难成名。九流者，土计孛同于官禄。土孛计会于官禄，宜是九流人也。', NULL, 0, 0, 1771384461);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('tu_011_huo_tu_ba_sha', '火土八杀', NULL, NULL, NULL, 'c_571f_661f_683c_5c40', NULL, NULL, '残疾者，火罗土杂于难宫。火罗土聚于八杀宫，必然残疾也。', NULL, 0, 0, 1771384461);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('tu_012_tu_zai_qi_wu', '土在齐吴', NULL, NULL, NULL, 'c_571f_661f_683c_5c40', NULL, NULL, '原夫土在齐吴，虽夜生而福尤昌炽（土居子丑）。', NULL, 0, 0, 1771384461);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('tu_013_huo_tu_de_niu', '火土得牛', NULL, NULL, NULL, 'c_571f_661f_683c_5c40', NULL, NULL, '火土会于牛宫，不独龟龄而已（火土会牛在丑）。', NULL, 0, 0, 1771384461);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('tu_014_tu_ju_zheng_guo', '土居郑国', NULL, NULL, NULL, 'c_571f_661f_683c_5c40', NULL, NULL, '土居郑国好亢，而正庙秤宫（土星在辰）。', NULL, 0, 0, 1771384461);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('tu_015_tu_hao_bao_ping', '土好宝瓶', NULL, NULL, NULL, 'c_571f_661f_683c_5c40', NULL, NULL, '参政学士，盖缘土好宝瓶（土星在子）。', NULL, 0, 0, 1771384461);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('tu_016_tu_mai_shuang_nv', '土埋双女', NULL, NULL, NULL, 'c_571f_661f_683c_5c40', NULL, NULL, '要知浅薄，无过土埋双女（土星在巳）。', NULL, 0, 0, 1771384461);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('tu_017_jin_tu_xiang_feng', '金土相逢', NULL, NULL, NULL, 'c_571f_661f_683c_5c40', NULL, NULL, '金土相逢，此辈盖能修合（金土指道门修合）。', NULL, 0, 0, 1771384461);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('tu_018_tu_hao_tai_chang', '土号太常', NULL, NULL, NULL, 'c_571f_661f_683c_5c40', NULL, NULL, '斗牛之次，土德庙地。土号太常。', NULL, 0, 0, 1771384461);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('tu_019_tu_luo_qian_yi', '土罗迁移', NULL, NULL, NULL, 'c_571f_661f_683c_5c40', NULL, NULL, '迁移犯土罗，男有旅亡之兆。土罗居迁移宫。', NULL, 0, 0, 1771384461);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('tu_020_tu_bei_si_gong', '土孛巳宫', NULL, NULL, NULL, 'c_571f_661f_683c_5c40', NULL, NULL, '火金子位，土孛巳宫，两相克战，切忌坐命。如此者非贫即夭。', NULL, 0, 0, 1771384461);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('tu_021_tu_xing_ru_ming', '土星入命', NULL, NULL, NULL, 'c_571f_661f_683c_5c40', NULL, NULL, '沉谋熟虑，为缘土入命宫。土主信，主人沉重敦厚。', NULL, 0, 0, 1771384462);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('tu_022_tu_ji_ju_chen', '土计居辰', NULL, NULL, NULL, 'c_571f_661f_683c_5c40', NULL, NULL, '脸面委黄，土计而居辰位。辰酉属胸膈。', NULL, 0, 0, 1771384462);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('tu_023_huo_yan_tu_zao', '火炎土燥', NULL, NULL, NULL, 'c_571f_661f_683c_5c40', NULL, NULL, '九夏之土逢火而燥。夏火太旺，生土反燥。', NULL, 0, 0, 1771384462);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('tu_024_tu_hui_jin_mai', '土晦金埋', NULL, NULL, NULL, 'c_571f_661f_683c_5c40', NULL, NULL, '金埋土而反晦。秋金土重反晦。', NULL, 0, 0, 1771384462);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('tu_025_tu_hun_shui_zhuo', '土混水浊', NULL, NULL, NULL, 'c_571f_661f_683c_5c40', NULL, NULL, '土混水而致浊。冬水冰结土混不清。', NULL, 0, 0, 1771384462);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('tu_026_shui_fan_tu_beng', '水泛土崩', NULL, NULL, NULL, 'c_571f_661f_683c_5c40', NULL, NULL, '受制之土见猛水，而崩溃四出。春夏生物之土乃为受制，遇水反崩溃。', NULL, 0, 0, 1771384462);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('tu_027_dong_tu_hui_huo', '冻土会火', NULL, NULL, NULL, 'c_571f_661f_683c_5c40', NULL, NULL, '冰冻之土会火，始能发用。', NULL, 0, 0, 1771384462);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('tu_028_han_tu_feng_jin', '寒土逢金', NULL, NULL, NULL, 'c_571f_661f_683c_5c40', NULL, NULL, '寒土何生金之有。所谓土寒者，不生之故。', NULL, 0, 0, 1771384462);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('tu_029_tu_mu_zhu_yue', '土母助月', NULL, NULL, NULL, 'c_571f_661f_683c_5c40', NULL, NULL, '辰酉坐命，土犯月而尤佳。金命喜土为母。', NULL, 0, 0, 1771384462);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('tu_030_shui_run_zao_tu', '水润燥土', NULL, NULL, NULL, 'c_571f_661f_683c_5c40', NULL, NULL, '刚燥之土遇水滋润。夏土干燥，爱水滋润。', NULL, 0, 0, 1771384462);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('tu_031_zhen_xing_ju_yuan', '镇星居垣', NULL, NULL, NULL, 'c_571f_661f_683c_5c40', NULL, NULL, '镇星居垣：土在子丑二宫。', NULL, 0, 0, 1771384462);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('tu_032_tu_xing_sheng_dian', '土星升殿', NULL, NULL, NULL, 'c_571f_661f_683c_5c40', NULL, NULL, '土星升殿：土躔女胃柳氐四宿。', NULL, 0, 0, 1771384462);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('tu_033_huo_tu_gao_qiang', '火土高强', NULL, NULL, NULL, 'c_571f_661f_683c_5c40', NULL, NULL, '火土高强：夏生火炎土燥，余月昼夜皆吉。', NULL, 0, 0, 1771384462);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('tu_034_tu_jin_jian_shi', '土金坚实', NULL, NULL, NULL, 'c_571f_661f_683c_5c40', NULL, NULL, '土金坚实：秋冬土埋金寒，余月皆妙。', NULL, 0, 0, 1771384462);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('tu_035_gou_chen_zhen_dian_2', '勾陈镇殿', NULL, NULL, NULL, 'c_571f_661f_683c_5c40', NULL, NULL, '勾陈镇殿：辰戌丑未月土，日同宫。土为勾陈星。', NULL, 0, 0, 1771384462);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('tu_036_tu_zai_mu_gong', '土在木宫', NULL, NULL, NULL, 'c_571f_661f_683c_5c40', NULL, NULL, '土在木宫：土在寅亥二宫。', NULL, 0, 0, 1771384462);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('tu_037_tu_ju_shui_di', '土居水地', NULL, NULL, NULL, 'c_571f_661f_683c_5c40', NULL, NULL, '土居水地：土在巳申二宫。', NULL, 0, 0, 1771384462);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('tu_038_mu_tu_xiang_ke', '木土相克', NULL, NULL, NULL, 'c_571f_661f_683c_5c40', NULL, NULL, '木土相克：木遇土而克。', NULL, 0, 0, 1771384462);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('tu_039_tu_shui_xiang_ji', '土水相激', NULL, NULL, NULL, 'c_571f_661f_683c_5c40', NULL, NULL, '土水相激：土克水之故。', NULL, 0, 0, 1771384462);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('tu_040_tu_luo_xiang_hui', '土罗相会', NULL, NULL, NULL, 'c_571f_661f_683c_5c40', NULL, NULL, '土罗相会：土为用神，居庙旺奇，夏生大燥。', NULL, 0, 0, 1771384462);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('tu_041_tu_ji_yan_yue', '土计掩月', NULL, NULL, NULL, 'c_571f_661f_683c_5c40', NULL, NULL, '土计掩月：夜月忌土计同宫，掌杀刃尤甚。', NULL, 0, 0, 1771384462);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('tu_042_tu_bei_hun_za', '土孛混杂', NULL, NULL, NULL, 'c_571f_661f_683c_5c40', NULL, NULL, '土孛混杂：土为用神则力轻忌格。', NULL, 0, 0, 1771384462);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('tu_043_qian_kun_pi_se', '乾坤否塞', NULL, NULL, NULL, 'c_571f_661f_683c_5c40', NULL, NULL, '乾坤否塞：亥命金罗，申命土计。', NULL, 0, 0, 1771384462);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('tu_044_ba_sha_chao_tian', '八杀朝天', NULL, NULL, NULL, 'c_571f_661f_683c_5c40', NULL, NULL, '八杀朝天：如戌命火，又未命土，或辰命金。此三星独占天门，得时为上。惟金火尤重，夜生显贵之人也。', NULL, 0, 0, 1771384462);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('tu_045_gou_chen_de_wei', '勾陈得位', NULL, NULL, NULL, 'c_571f_661f_683c_5c40', NULL, NULL, '四土星在辰戌丑未安命，乃勾陈得位。', NULL, 0, 0, 1771384462);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('tu_046_shui_tu_zao_xing', '水土遭刑', NULL, NULL, NULL, 'c_571f_661f_683c_5c40', NULL, NULL, '水木遭刑：歌云：申宫立命水为主，限戌恩金在奎度。金木相刑恩受制，反吉为凶横死鬼。限行亥宫见土星，土入江湖壁水度。也教富贵一时来，一十五年花锦丽。脱土半百危十五，溺死官刑骨肉忌。行奎度，在火宫则金受制，行亥见土，则能生金，金生水则发，到危则被土克。', NULL, 0, 0, 1771384462);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('tu_047_tu_xing_fei_da', '土星肥大', NULL, NULL, NULL, 'c_571f_661f_683c_5c40', NULL, NULL, '土星肥大：土星主人体重肥，为人禀性迟而愚。', NULL, 0, 0, 1771384462);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('tu_048_tu_ming_ji_mu', '土命忌木', NULL, NULL, NULL, 'c_571f_661f_683c_5c40', NULL, NULL, '土命忌木：木星刚健若无杀，土命嫌之有破克。', NULL, 0, 0, 1771384462);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('tu_049_tu_ke_rou_chuang', '土咳肉疮', NULL, NULL, NULL, 'c_571f_661f_683c_5c40', NULL, NULL, '土主咳嗽肉疮：土星为病必咳嗽，皮肉受病多生疮。', NULL, 0, 0, 1771384462);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('tu_050_tu_zou_shuang_yu', '土走双鱼', NULL, NULL, NULL, 'c_571f_661f_683c_5c40', NULL, NULL, '土走双鱼（翼度）。断躔，忌。', NULL, 0, 0, 1771384462);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('tu_051_tu_zou_ren_ma', '土走人马', NULL, NULL, NULL, 'c_571f_661f_683c_5c40', NULL, NULL, '土走人马位（尾度）断躔，忌。', NULL, 0, 0, 1771384462);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('tu_052_tu_hao_tai_chang_2', '土好太常', NULL, NULL, NULL, 'c_571f_661f_683c_5c40', NULL, NULL, '土星丑宫，贵格。', NULL, 0, 0, 1771384462);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('tu_053_tu_luo_xiang_hui_2', '土罗相会', NULL, NULL, NULL, 'c_571f_661f_683c_5c40', NULL, NULL, '土罗辰宫，贵格。', NULL, 0, 0, 1771384462);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('tu_054_mu_tu_xiang_hui', '木土相会', NULL, NULL, NULL, 'c_571f_661f_683c_5c40', NULL, NULL, '木土申宫，贵格。', NULL, 0, 0, 1771384462);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('tu_055_tu_ri_he_zhao', '土日合照', NULL, NULL, NULL, 'c_571f_661f_683c_5c40', NULL, NULL, '土日戌宫。', NULL, 0, 0, 1771384462);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('tu_056_tu_ji_ren_xiong', '土计刃雄', NULL, NULL, NULL, 'c_571f_661f_683c_5c40', NULL, NULL, '土计怕怒，忌掌刃雄廉耗等煞，水命限人尤凶。', NULL, 0, 0, 1771384462);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('tu_057_tu_xian_shan_beng', '土陷山崩', NULL, NULL, NULL, 'c_571f_661f_683c_5c40', NULL, NULL, '土星落空谓之土陷山崩，必主退败可畏，如有恶星降夹逼迫，多见气蹙噎吃之疾，必主倒限。', NULL, 0, 0, 1771384462);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('tu_058_tian_ao_bu_que', '填凹补缺', NULL, NULL, NULL, 'c_571f_661f_683c_5c40', NULL, NULL, '土星落空谓之土陷山崩，必主退败可畏，如有恶星降夹逼迫，多见气蹙噎吃之疾，必主倒限。如火会，谓之填凹补缺，又主名利发达。', NULL, 0, 0, 1771384462);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('tu_059_tian_di_jie_chun', '天地皆春', NULL, NULL, NULL, 'c_571f_661f_683c_5c40', NULL, NULL, '春令之土昼生与太阳交会，盖是阳和一点天地皆春，若有官令禄印爵魁佐之，主守成富贵，夜生最喜火照。土德朝拱太阳，盖火土俱名精彩，代日行权用事北方生者一人之下，万人之上，忠臣良将。土有生万物之功，其德至大，故得阳数五，三才五行皆不可失。', NULL, 0, 0, 1771384462);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('tu_060_ni_feng_fan_hua', '泥逢泛滑', NULL, NULL, NULL, 'c_571f_661f_683c_5c40', NULL, NULL, '春初生者，土计不宜与水孛交会，谓之泥逢泛滑。', NULL, 0, 0, 1771384462);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('tu_061_tu_xian_shan_beng_2', '土陷山崩', NULL, NULL, NULL, 'c_571f_661f_683c_5c40', NULL, NULL, '如土躔四水之度，又逢水孛，春末夏初生者，谓之土陷山崩，皆非好格，盖春初生者，土计不宜与水孛交会，谓之泥逢泛滑。四五月间洪水滔天，斯时土之气脉虚矣。', NULL, 0, 0, 1771384462);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('tu_062_tu_feng_shui_run', '土逢水润', NULL, NULL, NULL, 'c_571f_661f_683c_5c40', NULL, NULL, '夏令之土最喜水孛，若得同宫以润土之精神，斯时也，万物长养结实。遇水发生，清源可爱，富贵无言。', NULL, 0, 0, 1771384462);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('tu_063_huo_zao_tu_lie', '火燥土烈', NULL, NULL, NULL, 'c_571f_661f_683c_5c40', NULL, NULL, '夏末初秋之土，不宜与罗火交会，谓之火燥土烈，无水孛济，润万物摧枯，一落千丈，昼生土与太阳交辉，亦为日烈土焦。', NULL, 0, 0, 1771384462);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('tu_064_ri_lie_tu_jiao', '日烈土焦', NULL, NULL, NULL, 'c_571f_661f_683c_5c40', NULL, NULL, '夏末初秋之土，昼生土与太阳交辉，亦为日烈土焦。', NULL, 0, 0, 1771384463);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('tu_065_shang_sheng_xia_run', '上生下润', NULL, NULL, NULL, 'c_571f_661f_683c_5c40', NULL, NULL, '夏末初秋之土，不宜与罗火交会，谓之火燥土烈，无水孛济，润万物捣烂，一落千丈，昼生土与太阳交辉，亦为日烈土焦，如逢水孛，此谓上生下润，土之精彩，万物秀丽，大降吉祥。', NULL, 0, 0, 1771384463);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('tu_066_ri_wen_tu_hua', '日温土化', NULL, NULL, NULL, 'c_571f_661f_683c_5c40', NULL, NULL, '冬令之土最喜日温，自能变化。', NULL, 0, 0, 1771384463);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('tu_067_huo_luo_zhu_tu', '火罗助土', NULL, NULL, NULL, 'c_571f_661f_683c_5c40', NULL, NULL, '冬令之土，夜生木气火罗，佐助土之精神光彩，朝拱太阳皆主文武富贵，倘与水孛同躔极主贫寒，若得一木飞来泄水之气而又遇火飞来，合度此谓精神展转为妙。', NULL, 0, 0, 1771384463);
INSERT INTO ge_ju_patterns ("id", "name", "english_name", "pinyin", "aliases", "category_id", "keywords", "tags", "description", "origin_notes", "reference_count", "rule_count", "created_at") VALUES ('tu_068_tu_wei_zai_huan', '土为灾缓', NULL, NULL, NULL, 'c_571f_661f_683c_5c40', NULL, NULL, '土星为灾至缓，主病堆积滞难痊，使人晦涩，作事有头无尾，或出一月方发。土星行最迟二十九年一周天，故主疾淹滞。', NULL, 0, 0, 1771384463);
