BEGIN TRANSACTION;
CREATE TABLE "ge_ju_patterns" ("id" TEXT NOT NULL, "name" TEXT NOT NULL, "english_name" TEXT NULL, "pinyin" TEXT NULL, "aliases" TEXT NULL, "category_id" TEXT NOT NULL, "keywords" TEXT NULL, "tags" TEXT NULL, "description" TEXT NULL, "origin_notes" TEXT NULL, "reference_count" INTEGER NOT NULL DEFAULT 0, "rule_count" INTEGER NOT NULL DEFAULT 0, "created_at" INTEGER NOT NULL, PRIMARY KEY ("id"));
CREATE TABLE "ge_ju_schools" ("id" TEXT NOT NULL, "name" TEXT NOT NULL, "type" TEXT NOT NULL, "era" TEXT NULL, "founder" TEXT NULL, "description" TEXT NULL, "is_active" INTEGER NOT NULL DEFAULT 1 CHECK ("is_active" IN (0, 1)), "rule_count" INTEGER NOT NULL DEFAULT 0, "created_at" INTEGER NOT NULL, PRIMARY KEY ("id"));
CREATE TABLE "ge_ju_categories" ("id" TEXT NOT NULL, "name" TEXT NOT NULL, "order" INTEGER NOT NULL DEFAULT 0, "parent_id" TEXT NULL, "is_active" INTEGER NOT NULL DEFAULT 1 CHECK ("is_active" IN (0, 1)), "pattern_count" INTEGER NOT NULL DEFAULT 0, "created_at" INTEGER NOT NULL, PRIMARY KEY ("id"));
CREATE TABLE "ge_ju_rules" (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  pattern_id TEXT NOT NULL,
  school_id TEXT NOT NULL,
  jixiong TEXT NOT NULL,
  ge_ju_type TEXT NOT NULL,
  scope TEXT NOT NULL,
  coordinate_system TEXT,
  conditions TEXT,
  assertion TEXT,
  brief TEXT,
  chapter TEXT,
  original_text TEXT,
  explanation TEXT,
  notes TEXT,
  version TEXT NOT NULL,
  version_remark TEXT,
  is_active INTEGER NOT NULL DEFAULT 1,
  is_verified INTEGER NOT NULL DEFAULT 0,
  priority INTEGER NOT NULL DEFAULT 0,
  view_count INTEGER NOT NULL DEFAULT 0,
  created_at INTEGER NOT NULL,
  updated_at INTEGER NOT NULL,
  UNIQUE(pattern_id, school_id)
);
CREATE TABLE "ge_ju_versions" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "rule_id" INTEGER NOT NULL, "version" TEXT NOT NULL, "version_remark" TEXT NULL, "operation_type" TEXT NOT NULL, "changed_fields" TEXT NULL, "snapshot" TEXT NOT NULL, "diff_from_previous" TEXT NULL, "created_by" TEXT NOT NULL DEFAULT 'admin', "created_at" INTEGER NOT NULL);

诗曰：
太初丁丑岁为头，七政相逢会斗牛。
谁识当年差五日，连球合璧讵相侔。
[白话提要] 合璧，是相对于太阳和月亮而言的，是指太阳和月亮位于同一宫位。连珠，是相对于五星来说的，是指五星位于同一宫位，或是五星形成相互连接的格局。', NULL, 0, 0, 1771384454);
[白话提要] 太阳和月亮的合璧格局，包括同宫、对照或是三方拱合的关系。其中主要以入庙和乘旺最为贵气。太阳的运行轨道称为黄道，月亮的运行轨道称为白道。白道与黄道之间会形成一定的夹角。这种格局，便是形成四时八节的基础，对于辨别星空方位也有作用。', NULL, 0, 0, 1771384454);
[白话提要] 五星连珠，不需要五颗行星都位于同一宫中，而是相互之间按照一定的次序排列，与太阳、天门、太微、紫微等所在方位形成相互拱夹的格局。如果人能够遇到这种星命格局，则能够获得名望，身居高位。', NULL, 0, 0, 1771384454);
[白话提要] 斗牛，指的是斗宿和牛宿。秀气，指的是紫气星与斗、牛两个星宿之间形成相互呼应的关系。如果一个人的命宫在斗牛两宿所在的丑宫，则其人命运非凡。', NULL, 0, 0, 1771384454);
[白话提要] 这种星宿格局，是指日月和五星之间形成三合或对照的关系，而命宫位于亥宫。亥宫的五行属木，主管人的文章才气。所以将这种星命格局称为文章秘府。如果一个人遇到这种命格，则会见识广博，饱腹才学，能够享受到的福德也会很多。', NULL, 0, 0, 1771384454);
[白话提要] 五星朝斗，意思是五星位于双鱼宫中。因为双鱼宫对应的便是亥宫，亥宫在星空中代表天门，是天帝的离宫，各种星曜汇聚在这里，与北斗星形成相互拱合的格局。而北斗星位于紫微垣，代表官运旺盛。', NULL, 0, 0, 1771384454);
[白话提要] 月孛位于未宫的井宿。对于夜晚出生的人，则会获得权力。古代的太平的年代，不会遇到日食，也不会遇到月孛。月孛常常在天上顺行。如果遇到彗星，则会变得勇猛，机警，其人也会获得权力。', NULL, 0, 0, 1771384454);
[白话提要] 角宿和亢宿是东方苍龙的龙角所在位置。当罗睺位于辰宫的时候，就像是苍龙有了一个头一样。角亢与罗睺相互扶助。而人的命宫位于辰宫，这则会使人的命运获得显贵。', NULL, 0, 0, 1771384454);
[白话提要] 尾宿，在二十八宿之中，是苍龙的最后一个星宿。而计都星进入寅宫，则代表青龙有了龙尾。两者相互配合，会使人获得权力，位居高位。', NULL, 0, 0, 1771384454);
[白话提要] 阴阳同类，是说属性为阴或阳的星曜位于相同属性的星曜方位，则会获得辅助。就像是《易经》中说的，水会向着湿润的地方流淌，火会朝着干燥的地方蔓延一样，各种事物都会跟随同类发展变化。', NULL, 0, 0, 1771384454);
[白话提要] 北辰，就是北极星所在的方位。各种星曜都围绕着这个方位旋转运行，唯独它的位置不会发生变动。如果日月五星的命宫遇到这种格局，即使是与这个方位相互拱夹，都会使人获得权贵。', NULL, 0, 0, 1771384454);
[白话提要] 这是一种应当避免的忌格。因为罗睺是天神的头部，酉宫中有昴宿。命宫位于酉宫，又遇到罗睺和其他一些凶曜，则会使人遭受灾祸。', NULL, 0, 0, 1771384454);
[白话提要] 启明星，即水星；长庚，即金星。如果金星出现于命宫，则其人会才华横溢，而名满天下。上面还举了李白的例子，来说明这颗星的作用。', NULL, 0, 0, 1771384454);
[白话提要] 未宫代表巨獬神杀，是一种嫉恶如仇的神兽。如果月孛位于未宫，则不会形成凶相。对于命宫在未宫的人来说，如果遇到月孛则其人性情正直，敢于对他人提出批评。', NULL, 0, 0, 1771384454);
[白话提要] 扶桑，是指卯木。太阳运行到卯宫，如果没有其他的凶曜与其形成对照，则命宫位于卯宫，会使人获得富贵。', NULL, 0, 0, 1771384454);
[白话提要] 太阳快要出来的时候，各种阴气都开始隐藏起来，而风也会开始吹拂。如果太阳将要落山，则风也会停止。如果出生于丑日或是寅日，命宫也位于寅宫，朝向旺星的方向，则其人会获得好的名声。', NULL, 0, 0, 1771384454);
[白话提要] 月亮位于毕宿所在的方位，命宫在酉宫。如果是七八月出生的人，又能够获得水星的扶助，则会有利于运势。如果是三四月份出生，则会使其人四处漂泊。', NULL, 0, 0, 1771384454);
[白话提要] 月亮位于斗宿，对于人的才华会有帮助。唐朝的韩愈，宋代的苏东坡也都是这种命格。', NULL, 0, 0, 1771384454);
[白话提要] 五神，就是四个季节所对应的神位。如春天属木，所以木星为当令星。命宫在寅宫和卯宫，也属木，位于东方，所以是青龙用事；夏天属火，火星为当令星，命宫在巳宫和午宫，也属火，是南方朱雀掌管的方位。', NULL, 0, 0, 1771384454);
[白话提要] 如果一个人的命宫，被五星前后左右包围，则会使其人获得显贵的命运。', NULL, 0, 0, 1771384454);
[白话提要] 每月的月建所对应的宫位，都是北斗斗柄，即魁星所指向的方位。如果月亮运行到月建所对应的宫位，便形成了这种格局。', NULL, 0, 0, 1771384454);
[白话提要] 对于出生于每月初八或是二十三日午时的人，生性比较奸猾，因为此时的弦月刚刚开始形成，容易被海风吹袭，在海浪中出生。', NULL, 0, 0, 1771384454);
[白话提要] 禄元星和马元星是主管官禄的星曜，如果命宫与这两颗星处于相照的方位上，则会使其人仕途顺利；即使只是得到了这两颗星的帮助，也能够获得福德。', NULL, 0, 0, 1771384454);
[白话提要] 虎踞龙盘，是指命宫所在方位的宫主为金星，与木星形成对照的关系，如果在夜晚出生的人，则会形成这种格局。', NULL, 0, 0, 1771384454);
[白话提要] 这星命格局，是说水星和火星分别位于北方的坎卦方位和南方的离卦方位，如果是夜晚出生，火星在命宫中，而水星与火星形成正面对照的关系。则会使人获得优厚的俸禄；如果水星和火星同时位于命宫中，则会导致灾祸。', NULL, 0, 0, 1771384454);
[白话提要] 太阳为阳，代表君王，月亮为阴，代表王后。如果它们与吉星同时拱夹或对照命宫，则是吉相。如果与凶星位于同一宫位，则会产生灾祸。', NULL, 0, 0, 1771384454);
[白话提要] 春天出生的人，命宫通过寅宫和卯宫来确定。如果又遇到木星，则成为鳌头独步的格局。此时是被东方青龙所管辖。', NULL, 0, 0, 1771384454);
[白话提要] 太阳是火星的精华，月亮是水星的辅助，所以将太阳称为父，将火星称为子，将月亮称为母，将水星称为子。太阳的庙旺本应位于午宫，但是现在却位于子宫。而火星位于午宫，命宫也在午宫，这便称为子行父政。这会使得其人开始命运艰难，后来又安于享乐。', NULL, 0, 0, 1771384454);
[白话提要] 北斗星位于丑宫，如果命宫也在丑宫，又遇到三台星（即丑宫的前后都有吉祥的星曜），则会形成三台扶斗的格局。', NULL, 0, 0, 1771384454);
[白话提要] 天象运转，如果辰宫、巳宫、午宫和未宫上分别有一颗吉星，而命宫位于巳宫和午宫之间，则会形成吉星辅佐命宫的情况，其人会获得宰相一样的官职。', NULL, 0, 0, 1771384455);
[白话提要] 水星代表人的精气，而火星代表人的神气。如果命宫能够获得这两颗星曜，则称其为精神俱足。', NULL, 0, 0, 1771384455);
[白话提要] 金星和月亮同时位于亥宫或者辰宫，都称为月华金阙。如果金星与太阳同时位于亥宫和辰宫，则称为日华金阙。这两者都会使其人获得富贵。', NULL, 0, 0, 1771384455);
[白话提要] 太阳与罗睺同时位于未宫，月亮位于未宫，这便称为日中见斗。如果遇到日食，则会使得其人遭受灾祸。是一种应当避免的星命格局。', NULL, 0, 0, 1771384455);
[白话提要] 太阳在申宫和酉宫的方位落下，又受到罗睺的侵扰，如果命宫也位于申宫和酉宫，则称为明入地中。这种格局会使得太阳失去君王应有的地位，命宫位于这里，也被罗睺伤害。会使得其人祖业破败，经常遇到一些奇怪的事情。这也是应当避免的。', NULL, 0, 0, 1771384455);
[白话提要] 命宫位于申宫，而太阳位于寅宫；命宫在酉宫，而太阳位于卯宫；命宫在戌宫，而太阳在辰宫，这些情况都被称为明出地晋，需要获得金星和水星的辅助，才是贵气的星格。', NULL, 0, 0, 1771384455);
[白话提要] 木星和水星分别进入未宫的井宿中，会使得其间出生的人，品德高尚，获得福禄。', NULL, 0, 0, 1771384455);
[白话提要] 夜晚出生在坤卦方位的人遇到五星环绕月亮的星象，这便成为五星环月的星命格局。如果出现众星环月的星格，则需要根据它所处的宫位，以及星宿度数来进行判断。', NULL, 0, 0, 1771384455);
[白话提要] 金星位于乾卦的方位。因为乾卦位于西北亥宫，所以当金星运行到亥宫的时候，便形成了这种星命格局。', NULL, 0, 0, 1771384456);
[白话提要] 水星位于东南方位的巳宫，木星和命宫都位于寅宫。水星获得木星守卫命宫，便会形成水注东南的星格。对于酉时和寅时出生的人，如果遇到这种格局，则会获得福德，命运发达。', NULL, 0, 0, 1771384456);
[白话提要] 月孛也指的是天上的彗星，代表辞旧迎新，如果它照临大地，则会发生变易，它的形状像一把扫帚，可以扫除旧物，布置新生。', NULL, 0, 0, 1771384456);
[白话提要] 火星和水星在同一个宫位中，火星先进入，水星后进入，又和命宫相互对照，火星向上生发，水星向下注入，两者相互违背，而不能相互作用。所以称这种格局为火水未济，会使得其人一生贫穷，是需要避免的星格。', NULL, 0, 0, 1771384456);
[白话提要] 命宫位于子宫，木星代表的福德宫、财帛宫进入命宫，这便是福财克命的格局。如果木星遇到刑克的星曜，则会使得福财减半，如果命宫力量较弱，则会身不受财。', NULL, 0, 0, 1771384458);
[白话提要] 命宫位于丑宫的斗宿，土星运行到这个位置。行限位于辰宫，木星运行到角宿的方位，便称为角木断躔的格局。这会使得其人遭受杀身灾祸。', NULL, 0, 0, 1771384458);
[白话提要] 命宫位于寅宫的尾宿，又遇到金星，对于出生在寅年的人来说，则称为金骑人马。这会使得其人获得福禄。如果遇到罗睺，则会使其人成为奴仆，妻离子散。', NULL, 0, 0, 1771384458);
命立卯宫在房度。生于夏令主炎库。
行限午宫见水星。水入午宫宜柳土。
反凶为吉福无边。金玉争光敌国富。
若救脱水鬼门关。五十三四归泉路。
[白话提要] 命宫位于卯宫的房宿，对于出生于夏天的人来说，属火，遇到水星，便形成了水火相克的星格，会没有福德。如果此时土星位于柳宿，则会获得福报。', NULL, 0, 0, 1771384458);
[白话提要] 命宫位于辰宫亢宿，如果出生年干为乙，辰宫代表羊刃，如果遇到金星也位于亢宿，则能够成为边关的将军。如果行限到午宫，遇到火星进入柳宿，则会有财运。如果生在春天和夏天则会导致夭折或残疾。', NULL, 0, 0, 1771384458);
巳宫立命水在轸。玄武升垣诸杀顺。
又兼一点太白来。富贵绵绵应不窘。
若还中限见土星，重整门庭兴进永。
[白话提要] 命宫位于巳宫，水星位于轸宿，又遇到金星，则会获得富贵。如果行限遇到土星，则会使其人自立门户，获得兴旺。', NULL, 0, 0, 1771384458);
[白话提要] 命宫在午宫的星宿，火星进入这个方位，便占据了本应属于太阳的君位。而太阳只能位于卯宫的房宿，位于臣子的位置，这样父子异位，便会使得父子冲突，使其人遭受刑害。', NULL, 0, 0, 1771384458);
[白话提要] 命主位于未宫的井宿和木宿，如果出生在十五到十八的夜间，则月亮位于丑宫的斗宿，会使其人获得才华。如果月亮位于斗宿六度，或寅宫与斗宿相对应的方位，则会获得高官。行限到酉宫，土星位于胃宿，则会使其人遭受凶灾。', NULL, 0, 0, 1771384458);
[白话提要] 命宫在未宫，对于出生于初八到十五的人来说月亮与紫气同时运行，则会使其人获得才华和美貌。如果遇到罗睺，则成为二奴夹主的格局，会使其人遭遇孤苦。如果又遇到月孛，则会获得吉祥。行限位于酉宫，则获得富贵。位于戌宫，则会家破人亡。', NULL, 0, 0, 1771384458);
未宫立命月为主。夜令生人蟾蜍吐。
登时一孛抱阴精。早步青云登仕路。
计都飞伴两无情。不过十五归阴府。
[白话提要] 命宫位于未宫，对于夜晚出生的人来说，会获得月亮的精华，有利于获得功名。如果遇到计都，则会遇到凶灾。', NULL, 0, 0, 1771384458);
申宫立命水为主，限戌恩金在奎度。
金木相刑恩受制，反吉为凶横死鬼。
限行亥宫见土星，土入江湖壁水度。
也教富贵一时来，一十五年花锦丽。
脱土半百危十五。溺死官刑骨肉忌。
行奎度，在火宫则金受制，行亥见土，则能生金。金生水则发，到危则被土克。
[白话提要] 命宫位于申宫，行限到水星，金星位于奎宿，金木相刑害，恩星受到克制，会使得其人遭受凶灾。如果土星运行到亥宫，会获得一时的富贵。如果失去土星，则会遭受灾祸。', NULL, 0, 0, 1771384458);
[白话提要] 命宫位于酉宫，金星运行到丑宫的斗宿，这会使得其人才华横溢，长相俊秀，获得功名。如果行限位于寅宫的尾宿，遇到火星，则会遭受灾祸。而位于箕宿，则会获得福德和长寿。', NULL, 0, 0, 1771384458);
COMMIT;
